const shopStorageKey=()=>`gt_active_shop:${state.workspace?.id||'none'}`;
const rememberShopId=(shopId)=>{try{if(shopId)localStorage.setItem(shopStorageKey(),String(shopId))}catch{}};
const rememberedShopId=()=>{try{return localStorage.getItem(shopStorageKey())||''}catch{return ''}};
const isShopActive=(s)=>s&&s.status!=='archived';
const pickWorkingShop=(shops=[],preferredId='')=>{
  const list=Array.isArray(shops)?shops:[];
  const active=list.filter(isShopActive);
  const pref=String(preferredId||rememberedShopId()||'');
  return active.find(s=>s.id===pref)||list.find(s=>s.id===pref&&isShopActive(s))||active[0]||list[0]||null;
};

