const title=()=>({overview:'Магазины',catalog:'Товары',orders:'Заказы',customers:'Клиенты',storefront:'Витрина',campaigns:'Маркетинг',promotions:'Промо',automations:'Авто',analytics:'Аналитика',team:'Команда',payments:'Платежи',warehouse:'Склад',delivery:'Доставка',chats:'Клиенты',integrationsHub:'Интеграции',help:'Помощь',settings:'Настройки'})[state.route];
function shell(content){const initials=(state.me?.user?.name||'GT').split(/\s+/).map(p=>p[0]).join('').slice(0,2).toUpperCase();return `<div class="aurora" aria-hidden="true"><span class="island island-a"></span><span class="island island-b"></span><span class="island island-c"></span><span class="island island-d"></span></div><aside class="sidebar island-shell"><div class="brand"><span class="mark" aria-hidden="true"><i class="m-gt">G</i></span><b>Store</b></div><nav>${[['overview','home','Магазины'],['catalog','catalog','Товары'],['orders','orders','Заказы'],['delivery','delivery','Доставка'],['warehouse','warehouse','Склад'],['integrationsHub','integrations','Интеграции'],['customers','customers','Клиенты'],['campaigns','campaigns','Маркетинг'],['payments','payments','Платежи'],['analytics','analytics','Аналитика'],['team','team','Команда'],['help','help','Помощь'],['settings','settings','Настройки']].map(([r,i,l])=>`<button data-route="${r}" class="nav ${state.route===r?'active':''}">${icon(i)}${l}</button>`).join('')}</nav><div class="side-foot">© Store, 2026</div></aside><main><header class="island-header"><div><h1>${title()}</h1></div><div class="top-actions island-pill"><span class="active-shop-chip ${state.shop?.status==='archived'?'is-archived':''}" title="${state.shop?.status==='archived'?'Магазин в архиве':'Активный магазин'}">${state.shop?.status==='archived'?'Архив':'Активный'}: ${esc(state.shop?.name||'—')} · ${esc(state.shop?.slug||'—')}</span><select id="shop-switcher">${(state.shops||[]).filter(s=>s.status!=='archived'||s.id===state.shop?.id).map(s=>`<option value="${s.id}" ${state.shop?.id===s.id?'selected':''} ${s.status==='archived'?'disabled':''}>${esc(s.name)}${s.status==='archived'?' · архив':''}</option>`).join('')}</select><button class="ghost" id="logout">Выйти</button><div class="avatar" title="${esc(state.me?.user?.email||'')}">${esc(initials)}</div></div></header><section class="content">${content}</section></main>`}
function login(mode='login'){const inviteToken=new URLSearchParams(location.search).get('invite')||'';const isRegister=mode==='register';if(mode==='invite'||(inviteToken&&mode==='invite')){app.innerHTML=`<div class="login"><div class="aurora" aria-hidden="true"><span class="island island-a"></span><span class="island island-b"></span><span class="island island-c"></span></div><div class="login-card"><div class="brand big"><span class="mark" aria-hidden="true"><i class="m-gt">G</i></span><b>Store</b></div><h1>Приглашение</h1><p>Создайте пароль для входа.</p><form id="auth-form"><label>Имя<input name="name" required></label><label>Пароль<input name="password" type="password" required minlength="8"></label><input type="hidden" name="token" value="${esc(inviteToken)}"><button class="primary">Принять</button><button type="button" class="ghost wide" id="auth-switch">Ко входу</button><div id="error"></div></form></div></div>`;document.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.currentTarget));try{const accepted=await api('/team/invites/accept',{method:'POST',body});const data=await api('/auth/login',{method:'POST',body:{email:accepted.user.email,password:body.password}});session.token=data.token;history.replaceState({},'',location.pathname);await load()}catch(err){document.querySelector('#error').textContent=err.message}};document.querySelector('#auth-switch').onclick=()=>login('login');return}
  if(inviteToken&&mode==='login'){/* show invite CTA below */}
  app.innerHTML=`<div class="login"><div class="aurora" aria-hidden="true"><span class="island island-a"></span><span class="island island-b"></span><span class="island island-c"></span></div><div class="login-card"><div class="brand big"><span class="mark" aria-hidden="true"><i class="m-gt">G</i></span><b>Store</b></div><h1>${isRegister?'Регистрация':'Вход'}</h1><p>${isRegister?'Аккаунт и первый магазин.':'Telegram, MAX и Web.'}</p><form id="auth-form">${isRegister?'<label>Имя<input name="name" required placeholder="Имя"></label>':''}<label>Email<input name="email" type="email" required value="${isRegister?'':'owner@gtstore.local'}"></label><label>Пароль<input name="password" type="password" required minlength="8" value="${isRegister?'':'ChangeMe123!'}"></label>${isRegister?'<label>Магазин<input name="shopName" placeholder="Мой магазин"></label><label>Пространство<input name="workspaceName" placeholder="Моё пространство"></label>':''}<button class="primary">${isRegister?'Создать':'Войти'}</button><button type="button" class="ghost wide" id="auth-switch">${isRegister?'Уже есть аккаунт':'Регистрация'}</button>${isRegister?'':'<button type="button" class="ghost wide" id="bootstrap">Демо</button>'}${inviteToken?`<button type="button" class="ghost wide" id="open-invite">Приглашение</button>`:''}<div id="error"></div></form></div></div>`;
  document.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.currentTarget));try{if(isRegister){const data=await api('/auth/register',{method:'POST',body});session.token=data.token;await load()}else{const data=await api('/auth/login',{method:'POST',body});session.token=data.token;await load()}}catch(err){document.querySelector('#error').textContent=err.message}};
  document.querySelector('#auth-switch').onclick=()=>login(isRegister?'login':'register');
  document.querySelector('#open-invite')?.addEventListener('click',()=>login('invite'));
  const bootstrap=document.querySelector('#bootstrap');if(bootstrap)bootstrap.onclick=async()=>{try{await api('/bootstrap',{method:'POST',body:{email:'owner@gtstore.local',password:'ChangeMe123!',name:'Кирилл'}});document.querySelector('#error').textContent='Готово. Нажмите «Войти».'}catch(err){document.querySelector('#error').textContent=err.message}}}
async function load(){try{state.me=await api('/me');state.workspace=state.me.workspaces[0];if(!state.workspace){await createWorkspaceFlow();return}state.shops=await api(`/workspaces/${state.workspace.id}/shops`);const preferred=state.shop?.id||rememberedShopId();state.shop=pickWorkingShop(state.shops,preferred);if(state.shop)rememberShopId(state.shop.id);if(!state.shop){await createShopFlow();return}await Promise.all([loadCatalog(),loadOrders(),loadCustomers(),loadCampaigns()]);render()}catch{session.token='';login()}}
async function createWorkspaceFlow(){const name=prompt('Название пространства','Моё пространство');if(!name){session.token='';login();return}try{const created=await api('/workspaces',{method:'POST',body:{name,shopName:name}});state.workspace=created.workspace;state.shop=created.shop;state.shops=[created.shop];rememberShopId(created.shop.id);await load()}catch(err){alert(err.message);session.token='';login()}}
async function createShopFlow(){const name=prompt('Название магазина','Мой магазин');if(!name)return;try{const shop=await api(`/workspaces/${state.workspace.id}/shops`,{method:'POST',body:{name}});state.shop=shop;state.shops=[...(state.shops||[]),shop];rememberShopId(shop.id);await load()}catch(err){alert(err.message)}}
async function openShop(shopId,{navigate}={}){const shop=state.shops.find(s=>s.id===shopId);if(!shop||state.shop?.id===shopId)return;if(shop.status==='archived'){alert('Магазин в архиве. Сначала нажмите «Вернуть», чтобы сделать его активным.');return}state.shop=shop;rememberShopId(shop.id);state.products=[];state.catalogProducts=[];state.categories=[];state.categoryExpanded=new Set();state.orders=[];state.orderMetrics=null;state.customers=[];state.customerMetrics=null;state.campaigns=[];state.promotions=[];state.automations=[];state.storefront=null;state.versions=[];state.themePresets=[];state.telegram=null;state.apiKeys=[];state.referrals=[];state.referralProgram=null;state.paymentSettings=null;state.integrations=[];state.integrationDeliveries=[];state.integrationEvents=[];state.payments=[];state.inventory=[];state.warehouseMetrics=null;state.warehouseMovements=[];state.stocktakes=[];state.reservations=[];state.deliveryMethods=[];state.shipments=[];state.courierZones=[];state.apiship=null;state.maxChannel=null;state.chats=[];state.channelPosts=[];state.feeds=[];state.importJobs=[];state.erpConnections=[];state.integrationLogs=[];state.analytics=null;state.analyticsSettings=null;state.utmReport=null;state.helpArticles=[];state.helpSections=[];state.helpArticle=null;state.supportThread=null;state.supportTickets=[];state.team=null;state.selected.clear();state.query='';state.status='all';state.categoryId='';state.orderQuery='';state.orderStatus='all';state.customerQuery='';state.customerSegment='all';state.campaignStatus='all';state.automationFilter='all';state.paymentStatus='all';state.warehouseType='all';state.helpQuery='';state.helpSection='';state.supportDraft='';state.marketingTab='storefront';if(navigate)state.route=navigate;await Promise.all([loadCatalog(),loadOrders(),loadCustomers(),loadCampaigns()]);const r=state.route;if(r==='settings')await loadSettingsExtras();else if(r==='warehouse')await loadWarehouse();else if(r==='delivery')await loadDelivery();else if(r==='chats'||r==='customers')await Promise.all([loadCustomers(),loadChats()]);else if(r==='integrationsHub')await loadIntegrationsHub();else if(r==='help')await loadHelp();else if(r==='team')await loadTeam();else if(r==='payments')await loadPayments();else if(r==='analytics')await loadAnalytics();else if(r==='automations')await loadAutomations();else if(r==='campaigns'||r==='promotions'||r==='storefront')await loadMarketing();render();}async function logout(){try{await api('/auth/logout',{method:'POST'})}catch{}session.token='';state.me=null;state.workspace=null;state.shop=null;state.shops=[];document.querySelector('#support-fab')?.remove();login()}
async function loadCatalog(){if(!state.shop)return;const params=new URLSearchParams({q:state.query,status:state.status});const [categories,allProducts]=await Promise.all([api(root()+'/categories'),api(root()+'/products?'+params)]);state.categories=categories;state.catalogProducts=allProducts||[];if(state.categoryId){const ids=new Set([state.categoryId]);let grew=true;while(grew){grew=false;for(const c of state.categories){if(c.parentId&&ids.has(c.parentId)&&!ids.has(c.id)){ids.add(c.id);grew=true}}}state.products=state.catalogProducts.filter(p=>p.categoryId&&ids.has(p.categoryId))}else state.products=state.catalogProducts.slice();state.selected.clear()}
function shopStatusLabel(s){
  if(s?.status==='archived') return 'Архив';
  if(s?.id===state.shop?.id && s?.status!=='archived') return 'Активный';
  return 'Доступен';
}
function overview(){
  const author=state.me?.user?.name||'—';
  const shops=[...(state.shops||[])].sort((a,b)=>{
    const ar=a.status==='archived'?1:0, br=b.status==='archived'?1:0;
    if(ar!==br) return ar-br;
    return String(a.name||'').localeCompare(String(b.name||''),'ru');
  });
  return `<div class="page-actions"><button class="help-link" type="button" id="shop-help">ⓘ Как создать магазин</button><button class="primary" id="new-shop">+ Создать магазин</button></div><div class="shop-grid">${shops.map((s,i)=>{
    const archived=s.status==='archived';
    const active=s.id===state.shop?.id;
    return `<article class="shop-card${active?' active':''}${archived?' archived':''}" style="--i:${i}" ${archived?'':`data-open-shop="${s.id}"`}>
      <div class="shop-card-top">
        ${s.logoUrl?`<span class="shop-check shop-logo-mark" aria-hidden="true"><img src="${esc(mediaUrl(s.logoUrl))}" alt=""></span>`:`<span class="shop-check" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M5.5 12.5 10 17l8.5-9"/></svg></span>`}
        <h3>${esc(s.name)}</h3>
        <div class="shop-card-actions">
          ${archived
            ?`<button type="button" class="ghost" data-shop-restore="${s.id}">Вернуть</button>`
            :`<button type="button" class="ghost" data-shop-archive="${s.id}">В архив</button>`}
          <button type="button" class="ghost danger" data-shop-delete="${s.id}">Удалить</button>
        </div>
      </div>
      <div class="shop-card-meta">
        <div><small>Дата создания</small><b>${s.createdAt?new Date(s.createdAt).toLocaleDateString('ru-RU'):'—'}</b></div>
        <div><small>Автор магазина</small><b>${esc(author)}</b></div>
        <div><small>Мессенджер</small><b>Telegram</b></div>
        <div><i class="status ${archived?'cancelled':active?'paid':''}">${shopStatusLabel(s)}</i></div>
      </div>
    </article>`;
  }).join('')||`<div class="panel empty">${emptyIcon('home')}<h2>Нет магазинов</h2><p>Создайте первый магазин.</p></div>`}</div>`;
}
async function archiveShop(shopId){
  const shop=(state.shops||[]).find(s=>s.id===shopId);
  if(!shop) return;
  if(!confirm(`Отправить магазин «${shop.name}» в архив?\nВитрина и бот перестанут быть доступны публично.`)) return;
  try{
    const updated=await api(`/workspaces/${state.workspace.id}/shops/${shopId}`,{method:'PATCH',body:{status:'archived'}});
    state.shops=(state.shops||[]).map(s=>s.id===shopId?{...s,...updated}:s);
    if(state.shop?.id===shopId){
      const next=(state.shops||[]).find(s=>s.status!=='archived'&&s.id!==shopId);
      if(next) await openShop(next.id,{navigate:'overview'});
      else {state.shop={...state.shop,...updated};render()}
    } else render();
  }catch(err){alert(err.message)}
}
async function restoreShop(shopId){
  const shop=(state.shops||[]).find(s=>s.id===shopId);
  if(!shop) return;
  try{
    const updated=await api(`/workspaces/${state.workspace.id}/shops/${shopId}`,{method:'PATCH',body:{status:'published'}});
    state.shops=(state.shops||[]).map(s=>s.id===shopId?{...s,...updated}:s);
    rememberShopId(shopId);
    if(state.shop?.id===shopId){state.shop={...state.shop,...updated};render()}
    else {state.shop=null;await openShop(shopId,{navigate:'overview'})}
  }catch(err){alert(err.message)}
}
async function deleteShop(shopId){
  const shop=(state.shops||[]).find(s=>s.id===shopId);
  if(!shop) return;
  const ok=confirm(`Удалить магазин «${shop.name}» навсегда?\n\nБудут удалены товары, заказы, клиенты, настройки Telegram и весь кэш этого магазина. Это нельзя отменить.`);
  if(!ok) return;
  const confirmName=prompt(`Для подтверждения введите название магазина:\n${shop.name}`);
  if(confirmName!==shop.name){if(confirmName!=null) alert('Название не совпало — удаление отменено');return}
  try{
    const result=await api(`/workspaces/${state.workspace.id}/shops/${shopId}`,{method:'DELETE'});
    state.shops=(state.shops||[]).filter(s=>s.id!==shopId);
    if(state.shop?.id===shopId){
      const next=state.shops.find(s=>s.status!=='archived')||state.shops[0];
      if(next) await openShop(next.id,{navigate:'overview'});
      else {state.shop=null;await createShopFlow()}
    } else render();
    alert(`Магазин удалён. Очищено записей: ${result.purgedTotal??0}`);
  }catch(err){alert(err.message)}
}
function bindOverview(){
  document.querySelectorAll('[data-shop-archive]').forEach(btn=>btn.onclick=e=>{e.preventDefault();e.stopPropagation();archiveShop(btn.dataset.shopArchive)});
  document.querySelectorAll('[data-shop-restore]').forEach(btn=>btn.onclick=e=>{e.preventDefault();e.stopPropagation();restoreShop(btn.dataset.shopRestore)});
  document.querySelectorAll('[data-shop-delete]').forEach(btn=>btn.onclick=e=>{e.preventDefault();e.stopPropagation();deleteShop(btn.dataset.shopDelete)});
}

function flattenCategories(parentId=null,depth=0){return state.categories.filter(c=>c.active!==false&&(c.parentId||null)===(parentId||null)).sort((a,b)=>(a.position-b.position)||a.name.localeCompare(b.name,'ru')).flatMap(c=>[{...c,depth},...flattenCategories(c.id,depth+1)])}
function categoryOptions(selected='',{rootsOnly=false,excludeId=''}={}){const rows=flattenCategories().filter(c=>c.id!==excludeId&&(!rootsOnly||!c.parentId));return `<option value="">Без раздела</option>${rows.map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${' '.repeat(c.depth)}${c.depth?'↳ ':''}${esc(c.name)}</option>`).join('')}`}
function categoryHasChildren(id){return (state.categories||[]).some(c=>c.active!==false&&c.parentId===id)}
function ensureCategoryExpandedPath(categoryId){
  if(!(state.categoryExpanded instanceof Set)) state.categoryExpanded=new Set();
  let cur=(state.categories||[]).find(c=>c.id===categoryId);
  const seen=new Set();
  while(cur&&!seen.has(cur.id)){
    seen.add(cur.id);
    if(cur.parentId) state.categoryExpanded.add(cur.parentId);
    cur=(state.categories||[]).find(c=>c.id===cur.parentId);
  }
}
function categorySidebar(){
  if(!(state.categoryExpanded instanceof Set)) state.categoryExpanded=new Set();
  if(state.categoryId) ensureCategoryExpandedPath(state.categoryId);
  const countIn=catId=>{const ids=new Set([catId]);let grew=true;while(grew){grew=false;for(const c of state.categories){if(c.parentId&&ids.has(c.parentId)&&!ids.has(c.id)){ids.add(c.id);grew=true}}}return state.catalogProducts.filter(p=>p.categoryId&&ids.has(p.categoryId)).length};
  const visible=flattenCategories().filter(c=>{
    let cur=c;const seen=new Set();
    while(cur?.parentId&&!seen.has(cur.id)){
      seen.add(cur.id);
      if(!state.categoryExpanded.has(cur.parentId)) return false;
      cur=(state.categories||[]).find(x=>x.id===cur.parentId);
    }
    return true;
  });
  return visible.map(c=>{
    const hasKids=categoryHasChildren(c.id);
    const open=state.categoryExpanded.has(c.id);
    const twist=hasKids
      ?`<button type="button" class="cat-twist ${open?'open':''}" data-cat-toggle="${c.id}" title="${open?'Свернуть':'Развернуть'}" aria-label="${open?'Свернуть':'Развернуть'}" aria-expanded="${open?'true':'false'}">${open?'▾':'▸'}</button>`
      :`<span class="cat-twist spacer" aria-hidden="true"></span>`;
    return `<div class="category-row depth-${c.depth} ${state.categoryId===c.id?'active':''}" style="--depth:${c.depth}">${twist}<button type="button" class="category-item" data-category="${c.id}"><span class="category-label">${c.imageUrl?`<img class="category-thumb" src="${esc(mediaUrl(c.imageUrl))}" alt="">`:''}<span class="category-name">${esc(c.name)}${c.productDisplay==='flavors'?' <small class="cat-mode-tag">вкусы</small>':''}</span></span><span class="category-count">${countIn(c.id)}</span></button><div class="category-actions"><button type="button" class="icon-btn" data-edit-category="${c.id}" title="Изменить раздел" aria-label="Изменить">✎</button><button type="button" class="icon-btn danger" data-delete-category="${c.id}" title="Удалить раздел" aria-label="Удалить">×</button></div></div>`;
  }).join('');
}

function catalog(){return `<div class="catalog-layout"><aside class="category-panel panel"><div class="panel-head"><div><h3>Разделы</h3><small class="muted">раздел → подкатегория → линейка</small></div><button class="icon-btn" id="new-category" title="Новый раздел" aria-label="Новый раздел">+</button></div><button class="category-item ${!state.categoryId?'active':''}" data-category=""><span class="category-label">Все категории</span><span class="category-count">${(state.catalogProducts||state.products).length}</span></button>${categorySidebar()}<p class="muted category-hint">Стики → Terea → Армения. Или Стики → Neo → Толстые. Вкусы — в вариациях товара.</p></aside><div class="catalog-main"><div class="toolbar"><div class="search"><span class="search-ico" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="6.5"/><path d="m16.2 16.2 4.3 4.3"/></svg></span><input id="search" value="${esc(state.query)}" placeholder="Поиск по названию, SKU или бренду"></div><select id="status"><option value="all">Все статусы</option><option value="active" ${state.status==='active'?'selected':''}>Активные</option><option value="hidden" ${state.status==='hidden'?'selected':''}>Скрытые</option></select><button class="ghost" id="export-xlsx">Экспорт Excel</button><button class="ghost" id="import">Импорт</button><button class="primary" id="new-product">+ Товар</button></div>${state.selected.size?`<div class="bulkbar"><b>Выбрано: ${state.selected.size}</b><button class="ghost" data-bulk="show">Опубликовать</button><button class="ghost" data-bulk="hide">Скрыть</button><button class="ghost" data-bulk="stock">+10 к остатку</button></div>`:''}<div class="panel table"><div class="row head product-row"><span><input type="checkbox" id="select-all"></span><span>Товар</span><span>Артикул</span><span>Цена</span><span>Остаток</span><span>Статус</span><span></span></div>${state.products.length?state.products.map(p=>`<div class="row product-row"><span><input type="checkbox" data-select="${p.id}" ${state.selected.has(p.id)?'checked':''}></span><span class="product-name"><div class="thumb">${p.images?.[0]?`<img src="${esc(mediaUrl(p.images[0].url))}">`:`${ICONS.catalog}`}</div><span><b>${esc(p.name)}</b><small>${esc(p.brand||'Без бренда')} · ${p.variants?.length||0} вариаций</small></span></span><span class="mono">${esc(p.sku)}</span><span>${Number(p.price).toLocaleString('ru-RU')} ₽</span><span>${p.totalStock??p.stock}</span><span><button type="button" class="status status-toggle ${p.active?'on':'off'}" data-toggle-active="${p.id}" title="Нажмите, чтобы ${p.active?'скрыть':'активировать'}">${p.active?'Активен':'Скрыт'}</button></span><span class="actions"><button class="icon-btn" data-edit="${p.id}" aria-label="Редактировать"><svg viewBox="0 0 24 24" width="14" height="14" aria-hidden="true"><path d="M12 20h9M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4Z" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></button><button class="icon-btn danger" data-delete="${p.id}" aria-label="Удалить"><svg viewBox="0 0 24 24" width="14" height="14" aria-hidden="true"><path d="M18 6 6 18M6 6l12 12" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/></svg></button></span></div>`).join(''):`<div class="empty">${emptyIcon('catalog')}<h3>Ничего не найдено</h3><p>Измените фильтры или создайте первый товар.</p></div>`}</div></div></div>`}
async function loadTelegram(){state.telegram=await api(root()+'/telegram')}
async function loadSettingsExtras(){if(!state.shop)return;[state.telegram,state.apiKeys,state.referrals,state.paymentSettings,state.integrations,state.integrationDeliveries,state.integrationEvents,state.maxChannel,state.analyticsSettings]=await Promise.all([api(root()+'/telegram'),api(root()+'/api-keys'),api(root()+'/referrals'),api(root()+'/payments/settings'),api(root()+'/integrations'),api(root()+'/integrations/deliveries'),api('/integrations/events'),api(root()+'/max'),api(root()+'/analytics/settings')])}

function telegramPanelHtml(){const c=state.telegram||{connected:false,enabled:false,adminChatId:'',botUsername:'',welcomeMessage:'',shopButtonText:'Открыть магазин',webhookUrl:'',suggestedWebhookUrl:'',miniAppUrl:'',autoWebhook:false,publicBaseUrl:'',lastError:'',mode:''};const modeLabel=c.mode==='polling'?'Автоприём сообщений':c.mode==='webhook'?'Подключение по HTTPS':'—';const autoHint=c.storefrontHttps?'Mini App готов':(c.storefrontUrl?'Для Mini App нужен адрес витрины с HTTPS':'Укажите адрес витрины');const webhookValue=c.webhookUrl||c.suggestedWebhookUrl||'';const miniApp=c.miniAppUrl||'';const welcome=c.welcomeMessage||`Добро пожаловать в ${state.shop?.name||'магазин'}!\n\nОткройте каталог кнопкой ниже.`;const shopButton=c.shopButtonText||'Открыть магазин';return `<div class="panel telegram-settings"><div class="panel-head"><div><h2>${c.connected?'Telegram · @'+esc(c.botUsername):'Telegram'}</h2><small>${modeLabel} · ${autoHint}</small></div><i class="status ${c.connected?'paid':'cancelled'}">${c.connected?'Активен':'Не подключён'}</i></div><p class="muted" style="margin:0 0 14px">Бот, Mini App, уведомления о заказах и рассылки. Токен берётся в @BotFather.</p><div class="panel" style="margin:0 0 14px;padding:14px 16px"><p class="muted" style="margin:0 0 8px">Mini App (витрина) — привязывается сама при подключении:</p><code style="word-break:break-all">${miniApp?esc(miniApp):'Нужен адрес витрины с HTTPS'}</code><p class="muted" style="margin:10px 0 0">Адрес ниже — для приёма сообщений Telegram, это не ссылка на витрину.</p></div><form id="telegram-form" class="form-grid"><label class="full">Токен BotFather <small>${c.connected?'сохранён — оставьте пустым или вставьте новый':''}</small><input name="token" type="password" autocomplete="off" placeholder="${c.connected?'••••••••••••••••••••':'123456789:AA...'}" ${c.connected?'':'required'}></label><label>ID чата администратора<input name="adminChatId" value="${esc(c.adminChatId||'')}" placeholder="-1001234567890" required></label><label class="full">Адрес приёма сообщений <small>${c.mode==='webhook'&&c.webhookUrl?'активен':'можно оставить пустым'}</small><input name="webhookUrl" value="${esc(c.webhookUrl||'')}" placeholder="${esc(c.suggestedWebhookUrl||'https://…')}"></label><label class="full">Секрет подключения<input name="webhookSecret" placeholder="Пусто — сгенерировать автоматически"></label><label class="full">Приветствие при первом сообщении <small>отправляется, когда клиент открывает бота</small><textarea name="welcomeMessage" rows="5" maxlength="4096" placeholder="Добро пожаловать…">${esc(welcome)}</textarea></label><label class="full">Текст кнопки Mini App <small>кнопка под приветствием и в меню бота (до 64 символов, в меню — до 16)</small><input name="shopButtonText" value="${esc(shopButton)}" maxlength="64" placeholder="Открыть магазин" required></label><label class="check full"><input name="enabled" type="checkbox" ${c.enabled!==false?'checked':''}> Уведомления о новых заказах</label><div class="full modal-actions">${c.connected?'<button class="primary" name="intent" value="save">Сохранить настройки</button><button type="submit" class="ghost" name="intent" value="connect">Обновить токен / webhook</button><button type="button" class="ghost" id="telegram-test">Тестовое сообщение</button><button type="button" class="ghost danger" id="telegram-disconnect">Отключить</button>':'<button class="primary" name="intent" value="connect">Подключить бота</button>'}</div><div class="form-error full">${esc(c.lastError||'')}</div></form></div>`}
function bindTelegramForm(after){const form=document.querySelector('#telegram-form');if(!form)return;const saveSettings=async()=>{const err=form.querySelector('.form-error');err.textContent='';const welcomeMessage=form.welcomeMessage.value;const shopButtonText=form.shopButtonText.value;const adminChatId=form.adminChatId.value;const enabled=form.enabled.checked;if(!welcomeMessage.trim()){err.textContent='Введите текст приветствия';return}if(!shopButtonText.trim()){err.textContent='Введите текст кнопки Mini App';return}if(!adminChatId.trim()){err.textContent='Укажите Chat ID администратора';return}state.telegram=await api(root()+'/telegram',{method:'PATCH',body:{welcomeMessage,shopButtonText,adminChatId,enabled}});if(after)await after();else render()};form.onsubmit=async e=>{e.preventDefault();const submitter=e.submitter;const intent=submitter?.getAttribute?.('value')||submitter?.value||(state.telegram?.connected?'save':'connect');const data=Object.fromEntries(new FormData(form));data.enabled=form.enabled.checked;delete data.intent;const err=form.querySelector('.form-error');err.textContent='';try{if(intent==='save'||intent==='welcome'||(state.telegram?.connected&&!String(data.token||'').trim()&&intent!=='connect')){await saveSettings();return}if(!data.token&&!state.telegram?.connected){err.textContent='Укажите токен BotFather';return}if(!String(data.token||'').trim())delete data.token;if(!String(data.webhookUrl||'').trim())delete data.webhookUrl;if(!String(data.webhookSecret||'').trim())delete data.webhookSecret;if(!String(data.adminChatId||'').trim()&&state.telegram?.adminChatId)data.adminChatId=state.telegram.adminChatId;if(!String(data.shopButtonText||'').trim()&&state.telegram?.shopButtonText)data.shopButtonText=state.telegram.shopButtonText;state.telegram=await api(root()+'/telegram/connect',{method:'POST',body:data});if(after)await after();else render()}catch(err2){err.textContent=err2.message}};document.querySelector('#telegram-test')?.addEventListener('click',async()=>{try{await api(root()+'/telegram/test',{method:'POST'});alert('Тестовое сообщение отправлено')}catch(err){alert(err.message)}});document.querySelector('#telegram-disconnect')?.addEventListener('click',async()=>{if(!confirm('Отключить Telegram-бота?'))return;await api(root()+'/telegram',{method:'DELETE'});state.telegram=await api(root()+'/telegram');if(after)await after();else render()})}

function settingsPage(){const shop=state.shop||{};
return `<div class="settings-stack"><div class="panel"><div class="panel-head"><div><h2>Магазин</h2></div></div><form id="shop-settings-form" class="form-grid"><label>Название<input name="name" value="${esc(shop.name||'')}" required></label><label>Адрес витрины<input name="slug" value="${esc(shop.slug||'')}" required></label><label>Валюта<input name="currency" value="${esc(shop.currency||'RUB')}"></label><label>Часовой пояс<input name="timezone" value="${esc(shop.timezone||'Europe/Moscow')}"></label><div class="full shop-brand-row"><div class="shop-icon-card"><div class="shop-icon-preview" id="shop-logo-preview">${shop.logoUrl?`<img src="${esc(mediaUrl(shop.logoUrl))}" alt="Иконка магазина">`:`<span>${esc((shop.name||'G').trim().slice(0,1).toUpperCase())}</span>`}</div><div class="shop-icon-meta"><b>Иконка магазина</b><small>Шапка витрины, Mini App и вкладка браузера. PNG/JPG/WebP, лучше квадрат.</small><div class="shop-icon-actions"><label class="ghost upload-button compact">Загрузить / изменить<input id="logo-file" type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" hidden></label>${shop.logoUrl?`<button type="button" class="ghost compact danger" id="logo-clear">Удалить</button>`:''}</div></div><input type="hidden" name="logoUrl" value="${esc(shop.logoUrl||'')}"><input type="hidden" name="faviconUrl" value="${esc(shop.logoUrl||shop.faviconUrl||'')}"></div></div><div class="full modal-actions"><button class="primary">Сохранить магазин</button></div><div class="form-error full" id="shop-settings-error"></div></form></div><div class="panel telegram-settings"><div class="panel-head"><div><h2>Telegram</h2><small>Бот и Mini App настраиваются в разделе «Интеграции»</small></div><i class="status ${(state.telegram||{}).connected?'paid':'cancelled'}">${(state.telegram||{}).connected?'Активен · @'+esc((state.telegram||{}).botUsername||''):'Не подключён'}</i></div><div class="modal-actions"><button type="button" class="primary" id="goto-integrations-tg">Открыть интеграции</button></div></div><div class="panel"><div class="panel-head"><div><h2>Ключи доступа</h2></div><button class="primary" id="new-api-key">+ Ключ</button></div>${(state.apiKeys||[]).map(k=>`<p><b>${esc(k.name)}</b> · <code>${esc(k.prefix)}…</code> · ${esc((k.scopes||[]).join(', '))}<button class="icon-btn danger" data-revoke-key="${k.id}">×</button></p>`).join('')||'<p class="muted">Ключей пока нет.</p>'}</div><div class="panel"><div class="panel-head"><div><h2>ЮKassa</h2><small>${state.paymentSettings?.yookassa?.live?'подключена':'не настроена'}${state.paymentSettings?.yookassa?.source?' · '+esc(state.paymentSettings.yookassa.source):''}</small></div><i class="status ${state.paymentSettings?.yookassa?.live?'paid':'cancelled'}">${state.paymentSettings?.yookassa?.live?'Готово':'Выкл'}</i></div><form id="yookassa-form" class="form-grid"><label>ID магазина<input name="shopId" value="${esc(state.paymentSettings?.yookassa?.shopId||'')}" placeholder="123456"></label><label>Секретный ключ<input name="secretKey" type="password" placeholder="${state.paymentSettings?.yookassa?.secretKeySet?'Секрет сохранён — оставьте пустым':'live_...'}"></label><div class="full modal-actions"><button class="primary">Сохранить ЮKassa</button></div><div class="form-error full" id="yookassa-error"></div></form></div><div class="panel"><div class="panel-head"><div><h2>Уведомления</h2></div><button class="primary" id="new-webhook">+ Webhook</button></div>${(state.integrations||[]).map(h=>`<p><b>${esc(h.name)}</b> · <code>${esc(h.url)}</code> · ${esc((h.events||[]).join(', '))} · ${h.active!==false?'активен':'выкл'} <button class="ghost" data-test-hook="${h.id}">Тест</button><button class="ghost" data-rotate-hook="${h.id}">Ротация</button><button class="icon-btn danger" data-delete-hook="${h.id}">×</button></p>`).join('')||'<p class="muted">Webhook-ов пока нет.</p>'}<div class="toolbar"><h3>Доставки</h3></div><div class="panel table"><div class="row head"><span>Событие</span><span>Статус</span><span>Код</span><span>Дата</span><span>Ошибка</span></div>${(state.integrationDeliveries||[]).slice(0,20).map(d=>`<div class="row"><span>${esc(d.event)}</span><span>${esc(ru('deliveryStatus',d.status))}</span><span>${esc(d.statusCode??'')}</span><span>${d.createdAt?new Date(d.createdAt).toLocaleString('ru-RU'):'—'}</span><span>${esc(d.error||'')}</span></div>`).join('')||'<p class="muted">Доставок пока нет.</p>'}</div></div><div class="panel"><div class="panel-head"><div><h2>Я.Метрика и витрина</h2></div></div><form id="analytics-settings-form" class="form-grid"><label class="full">Счётчик Метрики<input name="metrikaId" value="${esc(state.analyticsSettings?.metrikaId||'')}" placeholder="12345678" inputmode="numeric"></label><div class="pay-methods pay-methods-stack full"><label class="pay-method${state.analyticsSettings?.cartEnabled!==false?' is-on':''}"><input name="cartEnabled" type="checkbox" ${state.analyticsSettings?.cartEnabled!==false?'checked':''}><span class="pay-method-box" aria-hidden="true"></span><span class="pay-method-label">Корзина на витрине</span></label><label class="pay-method${state.analyticsSettings?.showcaseOnly?' is-on':''}"><input name="showcaseOnly" type="checkbox" ${state.analyticsSettings?.showcaseOnly?'checked':''}><span class="pay-method-box" aria-hidden="true"></span><span class="pay-method-label">Только витрина (без корзины)</span></label></div><div class="full modal-actions"><button class="primary">Сохранить</button></div></form></div><div class="panel"><div class="panel-head"><div><h2>Рефералы</h2></div><button class="primary" id="new-referral">+ Реферал</button></div>${(state.referrals||[]).map(r=>`<p><b>${esc(r.name)}</b> · код <code>${esc(r.code)}</code> · uses ${r.uses||0} · reward ${r.rewardPercent}%</p>`).join('')||'<p class="muted">Реферальных кодов пока нет.</p>'}</div></div>`}
function bindSettings(){const shopForm=document.querySelector('#shop-settings-form');if(shopForm)shopForm.onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(shopForm));try{state.shop=await api(`/workspaces/${state.workspace.id}/shops/${state.shop.id}`,{method:'PATCH',body});state.shops=state.shops.map(s=>s.id===state.shop.id?state.shop:s);render()}catch(err){document.querySelector('#shop-settings-error').textContent=err.message}};const uploadBrand=async(input,field)=>{const file=input.files?.[0];if(!file)return;try{const uploaded=await api(root()+'/media',{method:'POST',body:{dataUrl:await fileToDataUrl(file),originalName:file.name}});const body={[field]:uploaded.url};if(field==='logoUrl')body.faviconUrl=uploaded.url;state.shop=await api(`/workspaces/${state.workspace.id}/shops/${state.shop.id}`,{method:'PATCH',body});state.shops=state.shops.map(s=>s.id===state.shop.id?state.shop:s);render()}catch(err){alert(err.message||'Не удалось загрузить изображение')}};const clearBrand=async()=>{try{state.shop=await api(`/workspaces/${state.workspace.id}/shops/${state.shop.id}`,{method:'PATCH',body:{logoUrl:'',faviconUrl:''}});state.shops=state.shops.map(s=>s.id===state.shop.id?state.shop:s);render()}catch(err){alert(err.message)}};const logo=document.querySelector('#logo-file');if(logo)logo.onchange=()=>uploadBrand(logo,'logoUrl');document.querySelector('#logo-clear')?.addEventListener('click',()=>{if(confirm('Удалить иконку магазина?'))clearBrand()});document.querySelector('#goto-integrations-tg')?.addEventListener('click',async()=>{state.route='integrationsHub';await loadIntegrationsHub();render()});document.querySelector('#new-api-key')?.addEventListener('click',()=>modal('Новый ключ доступа',`<label>Название<input name="name" required></label>`,async form=>{const created=await api(root()+'/api-keys',{method:'POST',body:Object.fromEntries(new FormData(form))});alert(`Сохраните ключ сейчас:\n${created.token}`);await loadSettingsExtras();render()}));document.querySelectorAll('[data-revoke-key]').forEach(b=>b.onclick=async()=>{if(confirm('Отозвать ключ?')){await api(root()+`/api-keys/${b.dataset.revokeKey}`,{method:'DELETE'});await loadSettingsExtras();render()}});document.querySelector('#new-referral')?.addEventListener('click',()=>modal('Новый реферал',`<label>Telegram ID<input name="telegram" required></label><label>Имя<input name="name"></label><label>Скидка %<input name="discountPercent" type="number" value="10"></label><label>Вознаграждение %<input name="rewardPercent" type="number" value="10"></label>`,async form=>{const body=Object.fromEntries(new FormData(form));body.discountPercent=Number(body.discountPercent);body.rewardPercent=Number(body.rewardPercent);await api(root()+'/referrals',{method:'POST',body});await loadSettingsExtras();render()}));const yk=document.querySelector('#yookassa-form');if(yk)yk.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(yk));const body={yookassa:{shopId:data.shopId||''}};if(data.secretKey)body.yookassa.secretKey=data.secretKey;try{state.paymentSettings=await api(root()+'/payments/settings',{method:'PUT',body});render()}catch(err){document.querySelector('#yookassa-error').textContent=err.message}};document.querySelector('#new-webhook')?.addEventListener('click',()=>{const events=state.integrationEvents?.length?state.integrationEvents:['order.created','order.updated','order.status_changed','customer.created','campaign.sent'];modal('Новый webhook',`<label>Название<input name="name" required></label><label class="full">URL<input name="url" type="url" required placeholder="https://..."></label><div class="full">${events.map(ev=>`<label class="check"><input type="checkbox" name="events" value="${esc(ev)}" checked> ${esc(ev)}</label>`).join('')}</div>`,async form=>{const fd=new FormData(form);const created=await api(root()+'/integrations',{method:'POST',body:{name:fd.get('name'),url:fd.get('url'),events:fd.getAll('events')}});if(created.signingSecret)alert('Signing secret:\n'+created.signingSecret);await loadSettingsExtras();render()})});document.querySelectorAll('[data-test-hook]').forEach(b=>b.onclick=async()=>{try{await api(root()+`/integrations/${b.dataset.testHook}/test`,{method:'POST'});await loadSettingsExtras();render();alert('Тест отправлен')}catch(err){alert(err.message)}});document.querySelectorAll('[data-rotate-hook]').forEach(b=>b.onclick=async()=>{if(!confirm('Ротировать secret?'))return;try{const r=await api(root()+`/integrations/${b.dataset.rotateHook}/rotate-secret`,{method:'POST'});if(r.signingSecret)alert('Новый secret:\n'+r.signingSecret);await loadSettingsExtras();render()}catch(err){alert(err.message)}});document.querySelectorAll('[data-delete-hook]').forEach(b=>b.onclick=async()=>{if(confirm('Удалить webhook?')){await api(root()+`/integrations/${b.dataset.deleteHook}`,{method:'DELETE'});await loadSettingsExtras();render()}});const analyticsForm=document.querySelector('#analytics-settings-form');if(analyticsForm){analyticsForm.querySelectorAll('.pay-method input[type=checkbox]').forEach(inp=>inp.addEventListener('change',()=>inp.closest('.pay-method')?.classList.toggle('is-on',inp.checked)));analyticsForm.onsubmit=async e=>{e.preventDefault();const fd=new FormData(analyticsForm);state.analyticsSettings=await api(root()+'/analytics/settings',{method:'PUT',body:{metrikaId:fd.get('metrikaId')||'',cartEnabled:analyticsForm.cartEnabled.checked,showcaseOnly:analyticsForm.showcaseOnly.checked}});render()}}}
async function loadPromotions(){if(!state.shop)return;state.promotions=await api(root()+'/promotions')}
function promotionsPage(){return `<div class="toolbar"><div><h2>Промокоды</h2></div><button class="primary" id="new-promo">+ Промокод</button></div><div class="panel table"><div class="row head"><span>Код</span><span>Тип</span><span>Значение</span><span>Использований</span><span>Статус</span><span></span></div>${(state.promotions||[]).map(p=>`<div class="row"><span><b>${esc(p.code)}</b></span><span>${esc(ru('promoType',p.type))}</span><span>${p.type==='percent'?p.value+'%':Number(p.value).toLocaleString('ru-RU')+' ₽'}</span><span>${p.usedCount||0}${p.usageLimit?' / '+p.usageLimit:''}</span><span><i class="status">${p.active!==false?'Активен':'Выкл'}</i></span><span><button class="ghost" data-toggle-promo="${p.id}">${p.active!==false?'Выключить':'Включить'}</button></span></div>`).join('')||`<div class="empty">${emptyIcon('promotions')}<h3>Промокодов пока нет</h3><p>Создайте первый промокод для клиентов.</p></div>`}</div>`}
function bindPromotions(){document.querySelector('#new-promo').onclick=()=>modal('Новый промокод',`<label>Код<input name="code" required minlength="3"></label><label>Тип<select name="type"><option value="percent">Процент</option><option value="fixed">Фикс</option></select></label><label>Значение<input name="value" type="number" min="1" required></label><label>Мин. сумма<input name="minSubtotal" type="number" min="0" value="0"></label><label>Лимит использований<input name="usageLimit" type="number" min="0" value="0"></label>`,async form=>{const body=Object.fromEntries(new FormData(form));body.value=Number(body.value);body.minSubtotal=Number(body.minSubtotal||0);body.usageLimit=Number(body.usageLimit||0);await api(root()+'/promotions',{method:'POST',body});await loadPromotions();render()});document.querySelectorAll('[data-toggle-promo]').forEach(b=>b.onclick=async()=>{const promo=state.promotions.find(p=>p.id===b.dataset.togglePromo);await api(root()+`/promotions/${promo.id}`,{method:'PATCH',body:{active:promo.active===false}});await loadPromotions();render()})}

async function loadAutomations(){if(!state.shop)return;state.automations=await api(root()+'/automations')}
const automationTriggerLabels={order_created:'Новый заказ',order_status_changed:'Статус заказа'};
const orderStatusLabels={new:'Новый',confirmed:'Подтверждён',awaiting_payment:'Ожидает оплату',paid:'Оплачен',assembling:'Собирается',ready:'Готов',shipped:'Передан в доставку',completed:'Завершён',cancelled:'Отменён',refunded:'Возврат'};
function automationsPage(){const items=state.automations.filter(r=>state.automationFilter==='all'||(state.automationFilter==='enabled'?r.enabled!==false:r.enabled===false));const totals=state.automations.reduce((a,r)=>{a.total+=Number(r.metrics?.total||0);a.sent+=Number(r.metrics?.sent||0);a.failed+=Number(r.metrics?.failed||0);a.pending+=Number(r.metrics?.pending||0);return a},{total:0,sent:0,failed:0,pending:0});return `<div class="campaign-head"><div><h2>Автоматизации</h2></div><button class="primary" id="new-automation">+ Сценарий</button></div><div class="metrics campaign-metrics">${[['Сценарии',state.automations.length,''],['Очередь',totals.pending,''],['Отправлено',totals.sent,''],['Ошибки',totals.failed,'']].map(([a,b,c])=>`<article><small>${a}</small><strong>${b}</strong><span>${c}</span></article>`).join('')}</div><div class="toolbar"><select id="automation-filter"><option value="all">Все сценарии</option><option value="enabled" ${state.automationFilter==='enabled'?'selected':''}>Включённые</option><option value="disabled" ${state.automationFilter==='disabled'?'selected':''}>Выключенные</option></select><button class="ghost" id="refresh-automations">Обновить</button></div><div class="automation-grid">${items.length?items.map(r=>`<article class="automation-card"><div class="automation-card-top"><span class="automation-state ${r.enabled!==false?'on':'off'}">${r.enabled!==false?'Активен':'Выключен'}</span><button class="icon-button" data-automation-menu="${r.id}">•••</button></div><h3>${esc(r.name)}</h3><div class="automation-flow"><span>${automationTriggerLabels[r.trigger]||r.trigger}${r.status?`: ${orderStatusLabels[r.status]||r.status}`:''}</span><b>→</b><span>${r.delayMinutes?`Через ${r.delayMinutes} мин.`:'Сразу'}</span><b>→</b><span>Telegram</span></div><p>${esc(r.message)}</p><div class="automation-stats"><span><b>${r.metrics?.sent||0}</b> отправлено</span><span><b>${r.metrics?.pending||0}</b> в очереди</span><span><b>${r.metrics?.failed||0}</b> ошибок</span></div><div class="automation-actions"><button class="ghost" data-automation-view="${r.id}">Журнал</button><button class="ghost" data-automation-edit="${r.id}">Изменить</button><label class="switch"><input type="checkbox" data-automation-toggle="${r.id}" ${r.enabled!==false?'checked':''}><span></span></label></div></article>`).join(''):`<div class="panel empty">${emptyIcon('automations')}<h2>Сценариев пока нет</h2><p>Создайте первое автоматическое сообщение для покупателей.</p></div>`}</div>`}
function automationEditor(rule={}){const modal=document.createElement('div');modal.className='modal-wrap';modal.innerHTML=`<div class="modal automation-modal"><button class="modal-close">×</button><h2>${rule.id?'Редактирование сценария':'Новый сценарий'}</h2><form id="automation-form"><label>Название<input name="name" required value="${esc(rule.name||'')}"></label><div class="form-grid"><label>Триггер<select name="trigger" id="automation-trigger"><option value="order_created" ${rule.trigger==='order_created'?'selected':''}>Создан новый заказ</option><option value="order_status_changed" ${rule.trigger==='order_status_changed'?'selected':''}>Изменился статус заказа</option></select></label><label id="automation-status-wrap">Статус<select name="status">${Object.entries(orderStatusLabels).map(([k,v])=>`<option value="${k}" ${rule.status===k?'selected':''}>${v}</option>`).join('')}</select></label></div><label>Задержка, минут<input name="delayMinutes" type="number" min="0" max="10080" value="${Number(rule.delayMinutes||0)}"></label><label>Сообщение<textarea name="message" rows="7" required>${esc(rule.message||'Здравствуйте, {{customer.name}}! Заказ №{{order.number}} принят.')}</textarea></label><div class="variable-row"><button type="button" data-var="{{customer.name}}">Имя</button><button type="button" data-var="{{order.number}}">Номер заказа</button><button type="button" data-var="{{order.total}}">Сумма</button><button type="button" data-var="{{order.status}}">Статус</button></div><label class="check-line"><input type="checkbox" name="enabled" ${rule.enabled!==false?'checked':''}> Сценарий включён</label><div class="form-error"></div><div class="modal-actions"><button type="button" class="ghost modal-cancel">Отмена</button><button class="primary">Сохранить сценарий</button></div></form></div>`;document.body.append(modal);const close=()=>modal.remove();modal.querySelector('.modal-close').onclick=close;modal.querySelector('.modal-cancel').onclick=close;const trigger=modal.querySelector('#automation-trigger'),wrap=modal.querySelector('#automation-status-wrap');const sync=()=>wrap.style.display=trigger.value==='order_status_changed'?'grid':'none';trigger.onchange=sync;sync();modal.querySelectorAll('[data-var]').forEach(b=>b.onclick=()=>{const t=modal.querySelector('[name="message"]');t.setRangeText(b.dataset.var,t.selectionStart,t.selectionEnd,'end');t.focus()});modal.querySelector('#automation-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=Object.fromEntries(new FormData(f));d.delayMinutes=Number(d.delayMinutes||0);d.enabled=f.enabled.checked;if(d.trigger!=='order_status_changed')d.status=null;try{if(rule.id)await api(root()+'/automations/'+rule.id,{method:'PATCH',body:d});else await api(root()+'/automations',{method:'POST',body:d});await loadAutomations();close();render()}catch(err){f.querySelector('.form-error').textContent=err.message}}}
async function automationDetails(id){const rule=await api(root()+'/automations/'+id);const modal=document.createElement('div');modal.className='modal-wrap';modal.innerHTML=`<div class="modal automation-modal wide"><button class="modal-close">×</button><h2>${esc(rule.name)}</h2><div class="run-list">${rule.runs?.length?rule.runs.map(run=>`<div class="run-row"><span class="status status-${run.status}">${run.status==='sent'||run.status==='success'?'Отправлено':run.status==='failed'||run.status==='error'?'Ошибка':run.status==='pending'||run.status==='queued'?'В очереди':run.status==='scheduled'?'Запланировано':esc(run.status)}</span><div><b>Заказ ${esc(run.orderId)}</b><small>${new Date(run.createdAt).toLocaleString('ru-RU')} · ${esc(run.telegramId)}</small></div><p>${esc(run.message)}</p><small>${run.reason?esc(run.reason):run.sentAt?'Отправлено '+new Date(run.sentAt).toLocaleString('ru-RU'):'Запланировано '+new Date(run.scheduledAt).toLocaleString('ru-RU')}</small></div>`).join(''):'<div class="empty"><p>Запусков ещё не было.</p></div>'}</div></div>`;document.body.append(modal);modal.querySelector('.modal-close').onclick=()=>modal.remove()}
function bindAutomations(){document.querySelector('#new-automation').onclick=()=>automationEditor();document.querySelector('#refresh-automations').onclick=async()=>{await loadAutomations();render()};document.querySelector('#automation-filter').onchange=e=>{state.automationFilter=e.target.value;render()};document.querySelectorAll('[data-automation-edit]').forEach(el=>el.onclick=()=>automationEditor(state.automations.find(r=>r.id===el.dataset.automationEdit)));document.querySelectorAll('[data-automation-view]').forEach(el=>el.onclick=()=>automationDetails(el.dataset.automationView));document.querySelectorAll('[data-automation-toggle]').forEach(el=>el.onchange=async()=>{await api(root()+'/automations/'+el.dataset.automationToggle,{method:'PATCH',body:{enabled:el.checked}});await loadAutomations();render()});document.querySelectorAll('[data-automation-menu]').forEach(el=>el.onclick=async()=>{const rule=state.automations.find(r=>r.id===el.dataset.automationMenu);if(confirm(`Удалить сценарий «${rule.name}»?`)){await api(root()+'/automations/'+rule.id,{method:'DELETE'});await loadAutomations();render()}})}

function placeholder(){return `<div class="panel empty"><h2>${title()}</h2></div>`}
function render(){if(state.route==='automations')state.route='overview';if(state.route==='chats')state.route='customers';app.innerHTML=shell(state.route==='overview'?overview():state.route==='catalog'?catalog():state.route==='orders'?ordersPage():state.route==='customers'?customersPage():state.route==='campaigns'?marketingPage():state.route==='promotions'?marketingPage():state.route==='analytics'?analyticsPage():state.route==='team'?teamPage():state.route==='payments'?paymentsPage():state.route==='warehouse'?warehousePage():state.route==='delivery'?deliveryPage():state.route==='integrationsHub'?integrationsHubPage():state.route==='help'?helpPage():state.route==='storefront'?marketingPage():state.route==='settings'?settingsPage():placeholder());document.querySelectorAll('[data-route]').forEach(el=>el.onclick=async()=>{state.route=el.dataset.route;if(state.route==='automations')state.route='overview';if(state.route==='chats')state.route='customers';if(state.route==='storefront'){state.marketingTab='storefront';await loadMarketing();}if(state.route==='customers')await Promise.all([loadCustomers(),loadChats()]);if(state.route==='orders')await loadOrders();if(state.route==='campaigns')await loadMarketing();if(state.route==='promotions'){state.marketingTab='promos';await loadMarketing();}if(state.route==='analytics')await loadAnalytics();if(state.route==='team')await loadTeam();if(state.route==='payments')await loadPayments();if(state.route==='warehouse')await loadWarehouse();if(state.route==='delivery')await loadDelivery();if(state.route==='integrationsHub')await loadIntegrationsHub();if(state.route==='help')await loadHelp();if(state.route==='settings')await loadSettingsExtras();render()});const logoutBtn=document.querySelector('#logout');if(logoutBtn)logoutBtn.onclick=()=>logout();const newShop=document.querySelector('#new-shop');if(newShop)newShop.onclick=async()=>{const name=prompt('Название магазина');if(!name)return;try{const shop=await api(`/workspaces/${state.workspace.id}/shops`,{method:'POST',body:{name}});state.shops=[...state.shops,shop];state.shop=shop;rememberShopId(shop.id);await Promise.all([loadCatalog(),loadOrders(),loadCustomers(),loadCampaigns()]);render()}catch(err){alert(err.message)}};document.querySelector('#shop-help')?.addEventListener('click',async()=>{state.route='help';state.helpQuery='магазин';await loadHelp();state.helpArticle=state.helpArticles.find(a=>a.id==='kb_start')||state.helpArticles[0]||null;render()});document.querySelectorAll('[data-open-shop]').forEach(card=>card.onclick=()=>openShop(card.dataset.openShop,{navigate:'catalog'}));if(state.route==='overview')bindOverview();const sw=document.querySelector('#shop-switcher');if(sw)sw.onchange=()=>openShop(sw.value);if(state.route==='catalog')bindCatalog();if(state.route==='orders')bindOrders();if(state.route==='customers'){bindCustomers();bindChats();}if(state.route==='campaigns'||state.route==='promotions'||state.route==='storefront')bindMarketing();if(state.route==='analytics')bindAnalytics();if(state.route==='team')bindTeam();if(state.route==='payments')bindPayments();if(state.route==='warehouse')bindWarehouse();if(state.route==='delivery')bindDelivery();if(state.route==='integrationsHub')bindIntegrationsHub();if(state.route==='help')bindHelp();if(state.route==='settings')bindSettings();bindSupportFab()}
function downloadBase64File({filename,base64,mimeType}){const bin=Uint8Array.from(atob(base64),c=>c.charCodeAt(0));const blob=new Blob([bin],{type:mimeType||'application/octet-stream'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename||'download.xlsx';a.click();URL.revokeObjectURL(a.href)}
async function exportCatalogXlsx(){try{const pack=await api(root()+'/export/xlsx');downloadBase64File(pack)}catch(err){alert(err.message)}}
function bindCatalog(){document.querySelector('#new-product').onclick=()=>productModal();document.querySelector('#new-category').onclick=()=>categoryModal();document.querySelector('#import').onclick=importModal;document.querySelector('#export-xlsx').onclick=exportCatalogXlsx;document.querySelector('#search').oninput=e=>{clearTimeout(bindCatalog.t);bindCatalog.t=setTimeout(async()=>{state.query=e.target.value;await loadCatalog();render()},250)};document.querySelector('#status').onchange=async e=>{state.status=e.target.value;await loadCatalog();render()};document.querySelectorAll('[data-cat-toggle]').forEach(btn=>btn.onclick=e=>{e.preventDefault();e.stopPropagation();if(!(state.categoryExpanded instanceof Set))state.categoryExpanded=new Set();const id=btn.dataset.catToggle;if(state.categoryExpanded.has(id))state.categoryExpanded.delete(id);else state.categoryExpanded.add(id);render()});document.querySelectorAll('[data-category]').forEach(el=>el.onclick=async()=>{state.categoryId=el.dataset.category;if(state.categoryId){ensureCategoryExpandedPath(state.categoryId);if(categoryHasChildren(state.categoryId))state.categoryExpanded.add(state.categoryId)}await loadCatalog();render()});document.querySelectorAll('[data-edit-category]').forEach(el=>el.onclick=e=>{e.stopPropagation();categoryModal(state.categories.find(c=>c.id===el.dataset.editCategory))});document.querySelectorAll('[data-delete-category]').forEach(el=>el.onclick=async e=>{e.stopPropagation();const cat=state.categories.find(c=>c.id===el.dataset.deleteCategory);if(!cat)return;if(!confirm(`Удалить раздел «${cat.name}» и все вложенные подкатегории? Товары останутся, но без этого раздела.`))return;try{const result=await api(root()+`/categories/${cat.id}?cascade=1`,{method:'DELETE'});if(result.deletedIds?.includes(state.categoryId))state.categoryId='';await loadCatalog();render()}catch(err){alert(err.message)}});document.querySelectorAll('[data-select]').forEach(el=>el.onchange=()=>{el.checked?state.selected.add(el.dataset.select):state.selected.delete(el.dataset.select);render()});const all=document.querySelector('#select-all');if(all)all.onchange=()=>{state.selected=new Set(all.checked?state.products.map(p=>p.id):[]);render()};document.querySelectorAll('[data-toggle-active]').forEach(el=>el.onclick=async()=>{const product=state.products.find(p=>p.id===el.dataset.toggleActive);if(!product)return;el.disabled=true;try{await api(root()+`/products/${product.id}`,{method:'PATCH',body:{active:!product.active}});await loadCatalog();render()}catch(err){el.disabled=false;alert(err.message||'Не удалось сменить статус')}});document.querySelectorAll('[data-edit]').forEach(el=>el.onclick=()=>productModal(state.products.find(p=>p.id===el.dataset.edit)));document.querySelectorAll('[data-delete]').forEach(el=>el.onclick=async()=>{if(confirm('Удалить товар без возможности восстановления?')){await api(root()+`/products/${el.dataset.delete}`,{method:'DELETE'});await loadCatalog();render()}});document.querySelectorAll('[data-bulk]').forEach(el=>el.onclick=async()=>{const action=el.dataset.bulk;const body={ids:[...state.selected]};if(action==='show')body.active=true;if(action==='hide')body.active=false;if(action==='stock')body.stockDelta=10;await api(root()+'/products/bulk',{method:'POST',body});await loadCatalog();render()})}
function modal(title,fields,onSubmit,size=''){const wrap=document.createElement('div');wrap.className='modal-wrap';wrap.innerHTML=`<form class="modal ${size}"><div class="panel-head"><h2>${title}</h2><button type="button" class="x">×</button></div>${fields}<div class="modal-actions"><button type="button" class="ghost cancel">Отмена</button><button class="primary">Сохранить</button></div><div class="form-error"></div></form>`;document.body.append(wrap);wrap.querySelectorAll('.x,.cancel').forEach(b=>b.onclick=()=>wrap.remove());wrap.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await onSubmit(e.currentTarget);wrap.remove();await loadCatalog();render()}catch(err){wrap.querySelector('.form-error').textContent=err.message}};return wrap}
function productModal(product=null){
 const variants=structuredClone(product?.variants||[]);const images=structuredClone(product?.images||[]);
 const wrap=modal(product?'Редактирование позиции':'Новая позиция',`<div class="form-grid"><label class="full">Название позиции<input name="name" value="${esc(product?.name||'')}" required placeholder="Например: Nasty Juice Slow Blow 60мл"></label><label>SKU<input name="sku" value="${esc(product?.sku||'')}" required></label><label>Бренд<input name="brand" value="${esc(product?.brand||'')}" placeholder="Nasty Juice"></label><label>Раздел / подкатегория / линейка<select name="categoryId">${categoryOptions(product?.categoryId)}</select></label><label>Цена (базовая)<input name="price" type="number" min="0" step="0.01" value="${product?.price??''}" required></label><label>Остаток (без вкусов)<input name="stock" type="number" min="0" value="${product?.stock??0}" required></label><div class="full media-editor"><div class="variants-head"><div><h3>Фото позиции</h3><p class="muted">Общее фото товара. Для каждого вкуса можно загрузить своё ниже.</p></div><label class="ghost upload-button">+ Загрузить<input id="media-files" type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple hidden></label></div><div id="media-gallery" class="media-gallery"></div></div><label class="full">Описание<textarea name="description">${esc(product?.description||'')}</textarea></label><div class="full variants-head"><div><h3>Вкусы / вариации</h3><p class="muted">Каждый вкус — отдельный SKU, цена, остаток и своё изображение.</p></div><button type="button" class="ghost" id="add-variant">+ Вкус</button></div><div class="full" id="variants"></div></div>`,async form=>{const val=sel=>form.querySelector(sel)?.value??'';const data={name:val('.form-grid > label.full > input[name="name"]'),sku:val('.form-grid > label:not(.full) > input[name="sku"]'),brand:val('input[name="brand"]'),categoryId:val('select[name="categoryId"]')||null,price:val('.form-grid > label:not(.full) > input[name="price"]'),stock:val('.form-grid > label:not(.full) > input[name="stock"]'),description:val('textarea[name="description"]')};if(!data.categoryId)delete data.categoryId;data.images=images.map((image,index)=>({...image,position:index,primary:index===0}));data.variants=[...form.querySelectorAll('.variant-row')].map((row,i)=>{const obj={};row.querySelectorAll('input[name]').forEach(inp=>obj[inp.name]=inp.value);const src=variants[i]||{};return{id:src.id||'',name:obj.variantName??obj.name,sku:obj.variantSku??obj.sku,price:obj.variantPrice??obj.price,stock:obj.variantStock??obj.stock,imageUrl:src.imageUrl||'',images:src.images||(src.imageUrl?[{url:src.imageUrl}]:[])}});const path=product?root()+`/products/${product.id}`:root()+'/products';await api(path,{method:product?'PATCH':'POST',body:data})},'large');
 const gallery=wrap.querySelector('#media-gallery');
 const uploadFiles=async files=>{for(const file of files){if(!String(file.type||'').startsWith('image/'))continue;const dataUrl=await fileToDataUrl(file);const uploaded=await api(root()+'/media',{method:'POST',body:{dataUrl,originalName:file.name,alt:product?.name||''}});images.push(uploaded)}drawImages()};
 const drawImages=()=>{gallery.innerHTML=images.length?images.map((image,index)=>`<article class="media-card"><img src="${esc(mediaUrl(image.url))}" alt=""><span>${index===0?'Обложка':`Фото ${index+1}`}</span><div><button type="button" class="icon-btn" data-left="${index}" ${index===0?'disabled':''}>←</button><button type="button" class="icon-btn" data-right="${index}" ${index===images.length-1?'disabled':''}>→</button><button type="button" class="icon-btn danger" data-remove-image="${index}">×</button></div></article>`).join(''):`<div class="media-empty">Перетащите или выберите изображения</div>`;gallery.querySelectorAll('[data-remove-image]').forEach(button=>button.onclick=async()=>{const image=images[Number(button.dataset.removeImage)];const filename=String(image?.url||'').split('/').pop();if(filename&&String(image.url||'').includes('/media/')){try{await api(root()+'/media/'+encodeURIComponent(filename),{method:'DELETE'})}catch{}}images.splice(Number(button.dataset.removeImage),1);drawImages()});gallery.querySelectorAll('[data-left]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.left);[images[i-1],images[i]]=[images[i],images[i-1]];drawImages()});gallery.querySelectorAll('[data-right]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.right);[images[i+1],images[i]]=[images[i],images[i+1]];drawImages()})};drawImages();
 gallery.ondragover=e=>{e.preventDefault();gallery.classList.add('drag-over')};gallery.ondragleave=()=>gallery.classList.remove('drag-over');gallery.ondrop=async e=>{e.preventDefault();gallery.classList.remove('drag-over');await uploadFiles(e.dataTransfer.files)};
 wrap.querySelector('#media-files').onchange=async event=>{await uploadFiles(event.target.files);event.target.value=''};
 const box=wrap.querySelector('#variants');
 const syncVariantFields=()=>{[...box.querySelectorAll('.variant-row')].forEach((row,i)=>{if(!variants[i])return;const data={};row.querySelectorAll('input[name]').forEach(inp=>data[inp.name]=inp.value);variants[i]={...variants[i],name:data.variantName??data.name,sku:data.variantSku??data.sku,price:Number(data.variantPrice??data.price??0),stock:Number(data.variantStock??data.stock??0)}})};
 const draw=()=>{box.innerHTML=variants.map((v,i)=>`<div class="variant-row flavor-row"><div class="flavor-thumb">${v.imageUrl||v.images?.[0]?.url?`<img src="${esc(mediaUrl(v.imageUrl||v.images[0].url))}" alt="">`:'<span>нет фото</span>'}<label class="ghost upload-button flavor-upload">Фото<input type="file" accept="image/*" data-flavor-img="${i}" hidden></label></div><div class="flavor-fields"><input name="variantName" value="${esc(v.name||'')}" placeholder="Вкус / цвет / размер (Amber или Белый;размер:S)"><input name="variantSku" value="${esc(v.sku||'')}" placeholder="SKU вкуса"><input name="variantPrice" type="number" value="${v.price??0}" placeholder="Цена"><input name="variantStock" type="number" value="${v.stock??0}" placeholder="Остаток"></div><button type="button" class="icon-btn danger" data-remove="${i}">×</button></div>`).join('')||'<p class="muted">Пока без вкусов — будет одна позиция с базовой ценой и остатком.</p>';box.querySelectorAll('[data-remove]').forEach(btn=>btn.onclick=()=>{syncVariantFields();variants.splice(Number(btn.dataset.remove),1);draw()});box.querySelectorAll('[data-flavor-img]').forEach(input=>input.onchange=async e=>{const i=Number(input.dataset.flavorImg);const file=e.target.files?.[0];if(!file)return;syncVariantFields();const dataUrl=await fileToDataUrl(file);const uploaded=await api(root()+'/media',{method:'POST',body:{dataUrl,originalName:file.name,alt:variants[i]?.name||'вкус'}});variants[i]={...variants[i],imageUrl:uploaded.url,images:[{url:uploaded.url,alt:variants[i]?.name||''}]};draw()})};draw();wrap.querySelector('#add-variant').onclick=()=>{syncVariantFields();variants.push({name:'',sku:'',price:Number(product?.price||0),stock:0,imageUrl:'',images:[]});draw()}}
function categoryModal(category){
  let imageUrl=category?.imageUrl||'';
  const display=category?.productDisplay==='flavors'?'flavors':'photos';
  const title=category?'Редактирование раздела':'Новый раздел / подкатегория / линейка';
  const wrap=modal(title,`<p class="muted full">До 3 уровней: <b>Стики</b> → <b>Terea / Neo</b> → <b>Армения / Толстые</b>. Режим отображения задаётся отдельно для каждого раздела и подкатегории.</p><label>Название<input name="name" required placeholder="Стики / Terea / Армения…" value="${category?esc(category.name):''}"></label><label>Внутри раздела<select name="parentId">${categoryOptions(category?.parentId||'',{excludeId:category?.id||''})}</select></label><label class="full">Отображение в Mini App<select name="productDisplay"><option value="photos" ${display==='photos'?'selected':''}>С фото товаров (плитки)</option><option value="flavors" ${display==='flavors'?'selected':''}>Список вкусов · фото этого раздела</option></select></label><p class="muted full">«Список вкусов» — сверху фото раздела/подкатегории, ниже строки вкусов с галочкой и добавлением в корзину. Удобно, когда у вкусов ещё нет своих фото.</p><div class="full category-image-editor"><div class="category-image-preview" id="category-image-preview">${imageUrl?`<img src="${esc(mediaUrl(imageUrl))}" alt="">`:'<span class="muted">Нет изображения</span>'}</div><label class="ghost upload-button">Загрузить картинку<input id="category-image-file" type="file" accept="image/*" hidden></label><button type="button" class="ghost danger" id="category-image-clear" ${imageUrl?'':'hidden'}>Убрать</button><input type="hidden" name="imageUrl" id="category-image-url" value="${esc(imageUrl)}"></div>`,async form=>{const body=Object.fromEntries(new FormData(form));body.imageUrl=imageUrl||'';body.productDisplay=body.productDisplay==='flavors'?'flavors':'photos';if(!body.parentId){if(category)body.parentId=null;else delete body.parentId;}if(category)await api(root()+`/categories/${category.id}`,{method:'PATCH',body});else await api(root()+'/categories',{method:'POST',body})});
  const preview=wrap.querySelector('#category-image-preview');
  const clearBtn=wrap.querySelector('#category-image-clear');
  const urlInput=wrap.querySelector('#category-image-url');
  const paint=()=>{preview.innerHTML=imageUrl?`<img src="${esc(mediaUrl(imageUrl))}" alt="">`:'<span class="muted">Нет изображения</span>';if(urlInput)urlInput.value=imageUrl||'';if(clearBtn)clearBtn.hidden=!imageUrl};
  wrap.querySelector('#category-image-file')?.addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;const uploaded=await api(root()+'/media',{method:'POST',body:{dataUrl:await fileToDataUrl(file),originalName:file.name,alt:category?.name||'category'}});imageUrl=uploaded.url;paint()});
  clearBtn?.addEventListener('click',()=>{imageUrl='';paint()});
}
