function tgNickLabel(c){const u=String(c?.telegramUsername||c?.username||'').replace(/^@/,'').trim();return u?`@${u}`:''}
function fmtDt(value){
  if(!value) return '';
  const d=new Date(value);
  if(Number.isNaN(d.getTime())) return '';
  return d.toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});
}
function visitLabel(c){
  const last=fmtDt(c?.lastSeenAt);
  const first=fmtDt(c?.firstSeenAt);
  const count=Number(c?.visitCount||0);
  const returned=Boolean(c?.returned)||count>=2;
  if(!last&&!first) return {title:'—',sub:'нет визитов'};
  return {
    title:last||first||'—',
    sub:returned?(count>1?`повторно · ${count}`:'повторно'):(count>1?`${count} визита`:'1 раз'),
  };
}
