async function openCustomerBroadcast(){
  if(!state.shop) return;
  if(!state.telegram){try{state.telegram=await api(root()+'/telegram')}catch{state.telegram=null}}
  const tgOk=Boolean(state.telegram?.connected&&state.telegram?.enabled!==false);
  let preview={count:Number(state.customerMetrics?.telegram||0),segment:'telegram'};
  try{preview=await api(root()+'/customers/broadcast/audience?segment=telegram')}catch{}
  const wrap=document.createElement('div');
  wrap.className='modal-wrap';
  wrap.innerHTML=`<form class="modal large customer-broadcast-modal"><div class="panel-head"><h2>Рассылка из бота</h2><button type="button" class="x">×</button></div>
    <p class="broadcast-lead">Сообщение уйдёт в личку Telegram тем, кто открывал бота или Mini App.</p>
    <div class="broadcast-meta">
      <div><small>Получатели</small><b id="broadcast-count">${Number(preview.count||0).toLocaleString('ru-RU')}</b></div>
      <div><small>Бот</small><b>${tgOk?(state.telegram?.botUsername?'@'+esc(state.telegram.botUsername):'подключён'):'не готов'}</b></div>
    </div>
    ${tgOk?'':`<p class="form-error" style="display:block">Сначала подключите и включите Telegram-бота в Настройках.</p>`}
    <div class="form-grid">
      <label>Аудитория
        <select name="segment" id="broadcast-segment">
          <option value="telegram" selected>Все, кто открывал бота / Mini App</option>
          <option value="new">Новые с Telegram</option>
          <option value="repeat">Повторные с Telegram</option>
          <option value="vip">VIP с Telegram</option>
        </select>
      </label>
      <label class="full">Название <span class="muted">(необязательно)</span>
        <input name="name" maxlength="120" placeholder="Например: Акция на выходные">
      </label>
      <label class="full">Текст сообщения
        <textarea name="message" rows="8" maxlength="4096" required placeholder="Текст рассылки…"></textarea>
        <small class="muted">До 4096 символов · обычный текст Telegram</small>
      </label>
    </div>
    <div class="modal-actions">
      <button type="button" class="ghost cancel">Отмена</button>
      <button type="submit" class="primary" id="broadcast-send" ${tgOk&&preview.count?'':'disabled'}>Отправить</button>
    </div>
    <div class="form-error"></div>
  </form>`;
  document.body.append(wrap);
  const close=()=>wrap.remove();
  wrap.querySelectorAll('.x,.cancel').forEach(b=>b.onclick=close);
  const countEl=wrap.querySelector('#broadcast-count');
  const sendBtn=wrap.querySelector('#broadcast-send');
  const errEl=wrap.querySelector('.form-error:last-child');
  const segEl=wrap.querySelector('#broadcast-segment');
  const refreshAudience=async()=>{
    try{
      const data=await api(root()+'/customers/broadcast/audience?segment='+encodeURIComponent(segEl.value));
      countEl.textContent=Number(data.count||0).toLocaleString('ru-RU');
      sendBtn.disabled=!tgOk||!data.count;
    }catch(err){errEl.textContent=err.message}
  };
  segEl.onchange=()=>refreshAudience();
  wrap.querySelector('form').onsubmit=async e=>{
    e.preventDefault();
    errEl.textContent='';
    const data=Object.fromEntries(new FormData(e.currentTarget));
    const text=String(data.message||'').trim();
    if(!text){errEl.textContent='Введите текст сообщения';return}
    if(!confirm(`Отправить сообщение ${countEl.textContent} получателям из бота?`)) return;
    sendBtn.disabled=true;sendBtn.textContent='Отправка…';
    try{
      const result=await api(root()+'/customers/broadcast',{method:'POST',body:{name:data.name,message:text,segment:data.segment||'telegram'}});
      close();
      const sent=Number(result.metrics?.sent||0), failed=Number(result.metrics?.failed||0), targeted=Number(result.metrics?.targeted||0);
      alert(`Рассылка завершена.\nПолучателей: ${targeted}\nДоставлено: ${sent}\nОшибок: ${failed}`);
      try{await loadCampaigns()}catch{}
      await loadCustomers();
      render();
    }catch(err){
      errEl.textContent=err.message||'Не удалось отправить';
      sendBtn.disabled=false;sendBtn.textContent='Отправить';
    }
  };
}

async function openCustomer(key){const c=await api(root()+`/customers/${encodeURIComponent(key)}`);const nick=tgNickLabel(c);const visit=visitLabel(c);const first=fmtDt(c.firstSeenAt);const fields=`<div class="customer-detail"><section><h3>${esc(c.name||nick||'Клиент')}</h3><p>${nick?esc(nick)+'<br>':''}${esc(c.phone||'')}${c.email?'<br>'+esc(c.email):''}${c.telegramId?'<br>Telegram ID: '+esc(c.telegramId):''}</p><div class="visit-card"><small>Визиты в бот / Mini App</small><strong>${esc(visit.title)}</strong><span>${first&&first!==visit.title?`Первый: ${esc(first)} · `:''}${esc(visit.sub)}</span></div><div class="loyalty-card"><small>Бонусный баланс</small><strong>${Number(c.bonusBalance).toLocaleString('ru-RU')}</strong><span>${esc(c.tier)} · кэшбэк ${c.cashback}%</span></div><label>Сегмент<select name="segment"><option value="new" ${c.segment==='new'?'selected':''}>Новый</option><option value="repeat" ${c.segment==='repeat'?'selected':''}>Повторный</option><option value="vip" ${c.segment==='vip'?'selected':''}>VIP</option></select></label><label>Заметки<textarea name="notes">${esc(c.notes||'')}</textarea></label></section><section><h3>История заказов</h3>${c.orders.map(o=>`<div class="order-line"><span>№${esc(o.number)} · ${new Date(o.createdAt).toLocaleDateString('ru-RU')}</span><b>${Number(o.total).toLocaleString('ru-RU')} ₽</b></div>`).join('')||'<p class="muted">Нет заказов</p>'}<h3>Бонусные операции</h3>${c.ledger.map(x=>`<div class="order-line"><span>${esc(x.reason)}</span><b>${x.amount>0?'+':''}${Number(x.amount).toLocaleString('ru-RU')}</b></div>`).join('')||'<p class="muted">Нет операций</p>'}<div class="crm-actions"><button type="button" class="ghost" id="bonus-add">Начислить бонусы</button><button type="button" class="ghost" id="promo-create">Создать промокод</button>${c.telegramId?`<button type="button" class="ghost" id="open-tg-chat">Чат в Telegram</button>`:''}</div></section></div>`;const wrap=modal('Карточка клиента',fields,async form=>{await api(root()+`/customers/${encodeURIComponent(key)}`,{method:'PATCH',body:Object.fromEntries(new FormData(form))});await loadCustomers()},'large');wrap.querySelector('#bonus-add').onclick=async()=>{const amount=prompt('Сумма бонусов. Для списания укажите отрицательное число:','500');if(amount)await api(root()+`/customers/${encodeURIComponent(key)}/bonus`,{method:'POST',body:{amount:Number(amount),reason:'Ручная корректировка'}});wrap.remove();await loadCustomers();render()};wrap.querySelector('#promo-create').onclick=async()=>{const discount=prompt('Скидка по персональному промокоду, %:','10');if(discount){const promo=await api(root()+`/customers/${encodeURIComponent(key)}/promos`,{method:'POST',body:{discount:Number(discount)}});alert(`Промокод: ${promo.code}`)}};wrap.querySelector('#open-tg-chat')?.addEventListener('click',async()=>{wrap.remove();const messages=await api(root()+`/chats/telegram/${encodeURIComponent(c.telegramId)}`);modal('Диалог Telegram',`<div class="full">${messages.map(m=>`<p><b>${esc(m.direction)}</b>: ${esc(m.text)}</p>`).join('')||'<p class="muted">Пусто</p>'}</div><label class="full">Ответ<textarea name="text" required></textarea>`,async form=>{const text=new FormData(form).get('text');await api(root()+'/chats/reply',{method:'POST',body:{channel:'telegram',externalUserId:c.telegramId,text}});await loadChats();render()},'wide')})}


async function loadCampaigns(){if(!state.shop)return;state.campaigns=await api(root()+'/campaigns')}
const campaignStatusLabels={draft:'Черновик',scheduled:'Запланирована',sending:'Отправляется',sent:'Отправлена',failed:'Ошибка',cancelled:'Отменена'};
const segmentLabels={all:'Все клиенты',telegram:'Бот / Mini App',new:'Новые',repeat:'Повторные',vip:'VIP'};
function marketingTabsHtml(){const tabs=[['storefront','Витрина'],['promos','Промокоды'],['campaigns','Мои рассылки'],['posting','Постинг'],['referrals','Реф. программа']];return `<nav class="mkt-tabs" aria-label="Разделы маркетинга">${tabs.map(([id,label])=>`<button type="button" class="mkt-tab ${state.marketingTab===id?'active':''}" data-mkt-tab="${id}">${label}</button>`).join('')}</nav>`}
function postingPage(){return `<div class="toolbar"><div><h2>Постинг</h2><small>Публикации в Telegram / MAX</small></div><button class="primary" id="channel-post">+ Пост</button></div><div class="panel table"><div class="row head"><span>Канал</span><span>Текст</span><span>Статус</span><span>Дата</span></div>${(state.channelPosts||[]).map(p=>`<div class="row"><span>${esc(p.channel==='max'?'MAX':p.channel==='telegram'?'Telegram':p.channel)}</span><span>${esc((p.text||'').slice(0,80))}</span><span>${esc(ru('postStatus',p.status))}</span><span>${p.createdAt?new Date(p.createdAt).toLocaleString('ru-RU'):'—'}</span></div>`).join('')||`<div class="empty">${emptyIcon('campaigns')}<h3>Постов пока нет</h3><p>Опубликуйте первый пост в канал.</p></div>`}</div>`}
function rewardFields(prefix,reward={},opts={}){const r=reward||{};return `<div class="ref-reward-grid"><label>Тип скидки<select name="${prefix}_type"><option value="percent" ${r.type!=='fixed'?'selected':''}>Процент</option><option value="fixed" ${r.type==='fixed'?'selected':''}>Фикс. сумма</option></select></label><label>Значение<input name="${prefix}_value" type="number" min="0" step="0.01" value="${Number(r.value??10)}" required></label><label>Мин. заказ, ₽<input name="${prefix}_minOrder" type="number" min="0" step="1" value="${Number(r.minOrder||0)}"></label><label>Срок промокода, дней<input name="${prefix}_validDays" type="number" min="0" step="1" value="${Number(r.validDays||14)}"></label>${opts.delay?`<label>Срок начисления после покупки, дней <small>защита от фрода</small><input name="${prefix}_delayDays" type="number" min="0" step="1" value="${Number(r.delayDays??0)}"></label>`:''}${opts.exclude?`<label class="check full"><input name="${prefix}_excludeDiscounted" type="checkbox" ${r.excludeDiscounted?'checked':''}> Не применять к товарам со скидкой</label>`:''}</div>`}
function referralsPage(){const p=state.referralProgram||{enabled:false,firstOrderOnly:true,referrerReward:{type:'percent',value:10,minOrder:0,validDays:30,delayDays:0},refereeReward:{type:'percent',value:10,minOrder:0,validDays:14,excludeDiscounted:false},analytics:{}};const a=p.analytics||{};return `<div class="ref-program settings-stack"><div class="toolbar"><div><h2>Реферальная программа</h2><small>10% другу на первый заказ · 10% бонусами пригласившему · ссылки привязаны к Telegram</small></div><label class="switch ref-enable"><input type="checkbox" id="ref-enabled" ${p.enabled?'checked':''} ${p.externalLoyaltyBlocked?'disabled':''}><span></span><b>Реферальная программа</b></label></div>${p.externalLoyaltyBlocked?`<div class="panel"><p class="danger">Нельзя включить при внешней системе лояльности (например Maxma).</p></div>`:''}<div class="metrics campaign-metrics">${[['Пригласивших',a.referrers||0,''],['Приглашённых',a.invited||0,''],['Заказов',a.orders||0,''],['Сумма заказов',`${Number(a.orderSum||0).toLocaleString('ru-RU')} ₽`,'']].map(([t,v,s])=>`<article><small>${t}</small><strong>${v}</strong><span>${s}</span></article>`).join('')}</div><form id="referral-program-form" class="settings-stack"><div class="panel"><label class="check full"><input name="firstOrderOnly" type="checkbox" ${p.firstOrderOnly!==false?'checked':''}> Только первый заказ приглашённого</label></div><div class="panel"><div class="panel-head"><div><h3>Награда пригласившему</h3><small>Бонусы на TG-аккаунт после покупки друга</small></div></div>${rewardFields('referrer',p.referrerReward,{delay:true})}</div><div class="panel"><div class="panel-head"><div><h3>Скидка приглашённому</h3><small>Скидка по реферальной ссылке</small></div></div>${rewardFields('referee',p.refereeReward,{exclude:true})}</div><div class="panel"><p class="muted">После включения у покупателей в профиле Mini App появится «Пригласи друга» с персональной ссылкой. Код привязан к Telegram ID клиента.</p><div class="modal-actions"><button class="primary" type="submit">Сохранить настройки</button></div><div class="form-error" id="referral-program-error"></div></div></form><div class="panel"><div class="panel-head"><div><h3>Персональные коды</h3><small>Генерируются автоматически для покупателей; можно добавить вручную</small></div><button class="ghost" id="new-referral" type="button">+ Код</button></div><div class="panel table"><div class="row head"><span>Название</span><span>Код</span><span>Использований</span><span>Награда</span></div>${(state.referrals||[]).map(r=>`<div class="row"><span><b>${esc(r.name)}</b>${r.auto?' <small class="muted">авто</small>':''}</span><span><code>${esc(r.code)}</code></span><span>${r.uses||0}</span><span>${Number(r.summary?.available||0).toLocaleString('ru-RU')} ₽ / ${Number(r.rewardPercent||0)}%</span></div>`).join('')||`<div class="empty"><h3>Кодов пока нет</h3><p>Они появятся, когда покупатели откроют «Пригласи друга».</p></div>`}</div></div></div>`}
async function loadReferralProgram(){if(!state.shop)return;[state.referralProgram,state.referrals]=await Promise.all([api(root()+'/referrals/program'),api(root()+'/referrals')])}
async function loadMarketing(){if(!state.shop)return;const tab=state.marketingTab||'storefront';if(tab==='storefront')await loadStorefront();else if(tab==='promos')await loadPromotions();else if(tab==='campaigns')await loadCampaigns();else if(tab==='posting')await loadChats();else if(tab==='referrals')await loadReferralProgram()}
function marketingPage(){const tab=state.marketingTab||'storefront';const body=tab==='storefront'?storefrontBuilder():tab==='promos'?promotionsPage():tab==='campaigns'?campaignsPanel():tab==='posting'?postingPage():referralsPage();return `<div class="marketing-page">${marketingTabsHtml()}<div class="marketing-body">${body}</div></div>`}
function bindMarketing(){document.querySelectorAll('[data-mkt-tab]').forEach(btn=>btn.onclick=async()=>{state.marketingTab=btn.dataset.mktTab;await loadMarketing();render()});const tab=state.marketingTab||'storefront';if(tab==='storefront'){if(typeof bindStorefront==='function')bindStorefront()}if(tab==='promos')bindPromotions();if(tab==='campaigns')bindCampaigns();if(tab==='posting'){document.querySelector('#channel-post')?.addEventListener('click',()=>modal('Пост в канал',`<label>Канал<select name="channel"><option value="telegram">Telegram</option><option value="max">MAX</option></select></label><label class="full">ID чата или канала<input name="channelId" placeholder="-100…"></label><label class="full">Текст<textarea name="text" rows="5" required></textarea></label>`,async form=>{const body=Object.fromEntries(new FormData(form));await api(root()+'/channel-posts',{method:'POST',body});await loadChats();render()}));}if(tab==='referrals'){const form=document.querySelector('#referral-program-form');const collect=()=>{const fd=new FormData(form);const pack=(prefix)=>({type:fd.get(`${prefix}_type`)||'percent',value:Number(fd.get(`${prefix}_value`)||0),minOrder:Number(fd.get(`${prefix}_minOrder`)||0),validDays:Number(fd.get(`${prefix}_validDays`)||0),delayDays:Number(fd.get(`${prefix}_delayDays`)||0),excludeDiscounted:Boolean(form.querySelector(`[name="${prefix}_excludeDiscounted"]`)?.checked)});return{enabled:Boolean(document.querySelector('#ref-enabled')?.checked),firstOrderOnly:Boolean(form.querySelector('[name="firstOrderOnly"]')?.checked),referrerReward:pack('referrer'),refereeReward:pack('referee')}};if(form)form.onsubmit=async e=>{e.preventDefault();const err=document.querySelector('#referral-program-error');try{state.referralProgram=await api(root()+'/referrals/program',{method:'PUT',body:collect()});await loadReferralProgram();render()}catch(ex){err.textContent=ex.message}};document.querySelector('#ref-enabled')?.addEventListener('change',async e=>{const err=document.querySelector('#referral-program-error');try{const body=collect();body.enabled=e.target.checked;state.referralProgram=await api(root()+'/referrals/program',{method:'PUT',body});await loadReferralProgram();render()}catch(ex){e.target.checked=!e.target.checked;if(err)err.textContent=ex.message}});document.querySelector('#new-referral')?.addEventListener('click',()=>modal('Новый реферал',`<label>Telegram ID<input name="telegram" required></label><label>Имя<input name="name"></label>`,async form=>{const body=Object.fromEntries(new FormData(form));await api(root()+'/referrals',{method:'POST',body});await loadReferralProgram();render()}));}}
function campaignsPanel(){const items=state.campaigns.filter(c=>state.campaignStatus==='all'||c.status===state.campaignStatus);const total=state.campaigns.length,sent=state.campaigns.reduce((n,c)=>n+Number(c.metrics?.sent||0),0),failed=state.campaigns.reduce((n,c)=>n+Number(c.metrics?.failed||0),0),scheduled=state.campaigns.filter(c=>c.status==='scheduled').length;return `<div class="campaign-head"><div><h2>Мои рассылки</h2></div><button class="primary" id="new-campaign">+ Кампания</button></div><div class="metrics campaign-metrics">${[['Кампании',total,''],['План',scheduled,''],['Доставлено',sent,''],['Ошибки',failed,'']].map(([a,b,c])=>`<article><small>${a}</small><strong>${b}</strong><span>${c}</span></article>`).join('')}</div><div class="toolbar"><select id="campaign-status"><option value="all">Все статусы</option>${Object.entries(campaignStatusLabels).map(([k,v])=>`<option value="${k}" ${state.campaignStatus===k?'selected':''}>${v}</option>`).join('')}</select><button class="ghost" id="refresh-campaigns">Обновить</button></div><div class="panel campaign-table"><div class="row head campaign-row"><span>Кампания</span><span>Сегмент</span><span>Статус</span><span>Результат</span><span>Запуск</span><span></span></div>${items.length?items.map(c=>`<button class="row campaign-row campaign-link" data-campaign="${c.id}"><span><b>${esc(c.name)}</b><small>${esc(c.message).slice(0,90)}${c.message.length>90?'…':''}</small></span><span>${segmentLabels[c.segment]||esc(c.segment)}</span><span><i class="status status-${c.status}">${campaignStatusLabels[c.status]||c.status}</i></span><span><b>${Number(c.metrics?.sent||0)}</b><small>ошибок: ${Number(c.metrics?.failed||0)}</small></span><span>${c.scheduledAt?new Date(c.scheduledAt).toLocaleString('ru-RU'):c.sentAt?new Date(c.sentAt).toLocaleString('ru-RU'):'—'}</span><span>→</span></button>`).join(''):`<div class="empty">${emptyIcon('campaigns')}<h3>Кампаний пока нет</h3><p>Создайте первую рассылку по клиентской базе.</p></div>`}</div>`}
function campaignFields(c={}){const local=c.scheduledAt?new Date(new Date(c.scheduledAt).getTime()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):'';return `<div class="form-grid"><label class="full">Название<input name="name" value="${esc(c.name||'')}" required maxlength="120"></label><label>Сегмент<select name="segment"><option value="all" ${c.segment==='all'?'selected':''}>Все клиенты</option><option value="telegram" ${c.segment==='telegram'?'selected':''}>Бот / Mini App</option><option value="new" ${c.segment==='new'?'selected':''}>Новые</option><option value="repeat" ${c.segment==='repeat'?'selected':''}>Повторные</option><option value="vip" ${c.segment==='vip'?'selected':''}>VIP</option></select></label><label>Дата и время отправки<input name="scheduledAt" type="datetime-local" value="${local}"></label><label class="full">Сообщение<textarea name="message" rows="8" maxlength="4096" required>${esc(c.message||'')}</textarea><small class="muted">До 4096 символов. Поддерживается обычный текст Telegram.</small></label></div>`}
function openCampaignEditor(c){const editable=!c||!['sending','sent','cancelled'].includes(c.status);const wrap=modal(c?'Кампания':'Новая кампания',editable?campaignFields(c):campaignDetails(c),async form=>{const data=Object.fromEntries(new FormData(form));data.scheduledAt=data.scheduledAt?new Date(data.scheduledAt).toISOString():null;await api(c?root()+`/campaigns/${c.id}`:root()+'/campaigns',{method:c?'PATCH':'POST',body:data});await loadCampaigns()},'large');if(c)attachCampaignActions(wrap,c)}
function campaignDetails(c){const deliveries=c.deliveries||[];return `<div class="campaign-detail"><section><span class="eyebrow">${segmentLabels[c.segment]||esc(c.segment)}</span><h2>${esc(c.name)}</h2><div class="message-preview">${esc(c.message).replace(/\n/g,'<br>')}</div><div class="campaign-summary"><span><small>Статус</small><b>${campaignStatusLabels[c.status]||c.status}</b></span><span><small>Аудитория</small><b>${Number(c.metrics?.targeted||0)}</b></span><span><small>Доставлено</small><b>${Number(c.metrics?.sent||0)}</b></span><span><small>Ошибки</small><b>${Number(c.metrics?.failed||0)}</b></span></div></section><section><h3>Журнал доставки</h3><div class="delivery-list">${deliveries.length?deliveries.map(d=>`<div><span><b>${esc(d.telegramId)}</b><small>${new Date(d.createdAt).toLocaleString('ru-RU')}</small></span><i class="status ${d.status==='failed'?'status-failed':'status-sent'}">${d.status==='sent'?'Доставлено':'Ошибка'}</i>${d.reason?`<small>${esc(d.reason)}</small>`:''}</div>`).join(''):'<p class="muted">Отправок ещё не было.</p>'}</div></section></div>`}
function attachCampaignActions(wrap,c){const footer=wrap.querySelector('.modal-actions');if(!footer)return;if(['draft','scheduled','failed'].includes(c.status)){const send=document.createElement('button');send.type='button';send.className='primary';send.textContent='Отправить сейчас';send.onclick=async()=>{if(confirm('Запустить рассылку сейчас?')){send.disabled=true;send.textContent='Отправка…';try{await api(root()+`/campaigns/${c.id}/send`,{method:'POST'});wrap.remove();await loadCampaigns();render()}catch(err){alert(err.message);send.disabled=false;send.textContent='Отправить сейчас'}}};footer.prepend(send)}if(['draft','scheduled','failed'].includes(c.status)){const cancel=document.createElement('button');cancel.type='button';cancel.className='ghost danger';cancel.textContent='Отменить кампанию';cancel.onclick=async()=>{if(confirm('Отменить кампанию?')){await api(root()+`/campaigns/${c.id}`,{method:'PATCH',body:{status:'cancelled'}});wrap.remove();await loadCampaigns();render()}};footer.prepend(cancel)}}
async function openCampaign(id){const c=await api(root()+`/campaigns/${id}`);openCampaignEditor(c)}
function bindCampaigns(){document.querySelector('#new-campaign').onclick=()=>openCampaignEditor();document.querySelector('#refresh-campaigns').onclick=async()=>{await loadCampaigns();render()};document.querySelector('#campaign-status').onchange=e=>{state.campaignStatus=e.target.value;render()};document.querySelectorAll('[data-campaign]').forEach(el=>el.onclick=()=>openCampaign(el.dataset.campaign))}


async function loadAnalytics(){state.analytics=await api(root()+`/analytics?days=${state.analyticsDays}`);state.utmReport=await api(root()+`/analytics/utm?days=${state.analyticsDays}`).catch(()=>null)}
const rub=value=>Number(value||0).toLocaleString('ru-RU')+' ₽';
function sparkline(series,key){const values=series.map(x=>Number(x[key]||0)),max=Math.max(1,...values);return `<div class="sparkline">${values.map((v,i)=>`<i title="${esc(series[i].date)}: ${v}" style="height:${Math.max(4,v/max*100)}%"></i>`).join('')}</div>`}
function analyticsPage(){const a=state.analytics;if(!a)return `<div class="panel empty"><h3>Загрузка…</h3></div>`;const m=a.metrics,maxFunnel=Math.max(1,...a.funnel.map(x=>x.value));return `<div class="analytics-toolbar"><div><h2>Аналитика</h2></div><select id="analytics-days"><option value="7" ${state.analyticsDays===7?'selected':''}>7 дней</option><option value="30" ${state.analyticsDays===30?'selected':''}>30 дней</option><option value="90" ${state.analyticsDays===90?'selected':''}>90 дней</option><option value="365" ${state.analyticsDays===365?'selected':''}>365 дней</option></select></div><div class="analytics-kpis">${[['Выручка',rub(m.revenue),'Оплаченные заказы'],['Заказы',m.orders,'Без отмен и возвратов'],['Средний чек',rub(m.averageOrder),'По действительным заказам'],['Конверсия',m.conversion+'%','Заказы / визиты'],['Новые клиенты',m.newCustomers,'За весь период'],['Повторные',m.repeatCustomers,'Два заказа и больше']].map(([l,v,s])=>`<article class="panel"><small>${l}</small><strong>${v}</strong><span>${s}</span></article>`).join('')}</div><div class="analytics-grid"><section class="panel analytics-chart"><div class="panel-head"><div><small>ДИНАМИКА</small><h3>Выручка и заказы</h3></div></div>${sparkline(a.series,'revenue')}<div class="chart-legend"><span>Выручка: ${rub(m.revenue)}</span><span>Заказов: ${m.orders}</span><span>Визитов: ${m.visits}</span></div></section><section class="panel"><div class="panel-head"><div><small>ВОРОНКА</small><h3>Путь покупателя</h3></div></div><div class="funnel">${a.funnel.map((x,i)=>`<div><span>${esc(x.label)} <b>${x.value}</b></span><i style="width:${Math.max(3,x.value/maxFunnel*100)}%"></i>${i?`<small>${a.funnel[i-1].value?Math.round(x.value/a.funnel[i-1].value*100):0}% от прошлого этапа</small>`:''}</div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><small>ТОВАРЫ</small><h3>Лидеры продаж</h3></div></div><div class="analytics-list">${a.topProducts.length?a.topProducts.map((p,i)=>`<div><span><b>${i+1}. ${esc(p.name)}</b><small>${p.quantity} шт.</small></span><strong>${rub(p.revenue)}</strong></div>`).join(''):'<p class="muted">Продаж пока нет.</p>'}</div></section><section class="panel"><div class="panel-head"><div><small>ИСТОЧНИКИ</small><h3>Каналы заказов</h3></div></div><div class="analytics-list">${a.sources.length?a.sources.map(s=>`<div><span><b>${esc(s.source)}</b><small>${s.visits||0} визитов · ${s.orders||0} заказов</small></span><strong>${rub(s.revenue||0)}</strong></div>`).join(''):'<p class="muted">Источники пока не определены.</p>'}</div></section><section class="panel comm-card"><div><small>КАМПАНИИ</small><strong>${a.campaigns.sent}</strong><span>доставлено из ${a.campaigns.targeted}</span></div><div><small>ОШИБКИ</small><strong>${a.campaigns.failed}</strong><span>${a.campaigns.campaigns} кампаний</span></div></section><section class="panel comm-card"><div><small>АВТОМАТИЗАЦИИ</small><strong>${a.automations.sent}</strong><span>успешных запусков</span></div><div><small>ОЧЕРЕДЬ / ОШИБКИ</small><strong>${a.automations.pending} / ${a.automations.failed}</strong><span>${a.automations.rules} сценариев</span></div></section><section class="panel utm-report"><div class="panel-head"><div><small>UTM</small><h3>Источники трафика</h3></div></div><div class="row head"><span>Источник</span><span>Канал</span><span>Кампания</span><span>Заказы</span><span>Выручка</span></div>${(state.utmReport?.rows||[]).length?(state.utmReport.rows.map(r=>`<div class="row"><span>${esc(r.source)}</span><span>${esc(r.medium)}</span><span>${esc(r.campaign)}</span><span>${r.orders}</span><span>${rub(r.revenue)}</span></div>`).join('')):'<p class="muted">Заказов с UTM-метками пока нет.</p>'}</section></div>`}
function bindAnalytics(){document.querySelector('#analytics-days').onchange=async e=>{state.analyticsDays=Number(e.target.value);await loadAnalytics();render()}}


async function loadPayments(){state.payments=await api(root()+'/payments?status='+encodeURIComponent(state.paymentStatus));try{state.paymentSettings=await api(root()+'/payments/settings')}catch{}}
function paymentsPage(){const ps=state.paymentSettings||{};const providers=ps.providers||[];const legal=ps.legal||{};const cm=ps.checkoutMethods||{cash:true,transfer:true,yookassa:true,tbank:true,tochka:true,yapay:true,split:true};const checkoutOpts=[['cash','При получении'],['transfer','Перевод'],['yookassa','ЮKassa'],['tbank','Т‑Банк'],['tochka','Точка'],['yapay','Я.Пэй'],['split','Сплит']];return `<div class="toolbar"><div><h2>Платежи</h2></div><select id="payment-status"><option value="all">Все статусы</option>${ruOptions('payStatus',['pending','authorized','paid','cancelled','expired','refunded','failed'],state.paymentStatus)}</select><button class="ghost" id="payment-legal">Юр.данные / НДС</button><button class="primary" id="payment-providers">Провайдеры</button></div><div class="panel"><div class="panel-head"><div><h3>Способы на витрине</h3><small>Отметьте, что увидит клиент при оформлении заказа</small></div><button class="primary" id="save-checkout-methods">Сохранить</button></div><div class="pay-methods" id="checkout-methods-form">${checkoutOpts.map(([id,label])=>`<label class="pay-method${cm[id]!==false?' is-on':''}"><input type="checkbox" name="${id}" ${cm[id]!==false?'checked':''}><span class="pay-method-box" aria-hidden="true"></span><span class="pay-method-label">${label}</span></label>`).join('')}</div></div><div class="metrics">${providers.filter(p=>p.mode==='online').slice(0,6).map(p=>`<article><small>${esc(p.name)}</small><strong>${p.live?'рабочий':p.implemented?'тест':'—'}</strong><span>${esc(p.code)}</span></article>`).join('')}</div><div class="panel table"><div class="row head"><span>Платёж</span><span>Провайдер</span><span>Сумма</span><span>Статус</span><span></span></div>${state.payments.map(p=>`<div class="row"><span><b>${esc(p.id)}</b><small>Заказ ${esc(p.orderId)}${p.receiptId?' · чек':''}</small></span><span>${esc(ru('provider',p.provider))}${p.live===false?' · тест':''}</span><span>${Number(p.amount||0).toLocaleString('ru-RU')} ${esc(p.currency||'RUB')}</span><span><i class="status ${esc(p.status)}">${esc(ru('payStatus',p.status))}</i></span><span class="actions">${p.status==='pending'||p.status==='authorized'?`<button class="ghost" data-check-payment="${p.id}">Проверить</button>`:''}${p.status==='paid'?`<button class="ghost danger" data-refund-payment="${p.id}">Возврат</button>`:''}</span></div>`).join('')||`<div class="empty">${emptyIcon('payments')}<h3>Платежей пока нет</h3><p>Платежи появятся после онлайн-оплат.</p></div>`}</div><div class="panel"><small>Юрлицо: ${esc(legal.companyName||'не задано')} · ИНН ${esc(legal.inn||'—')} · НДС ${legal.vatRate??20}%</small></div>`}
function bindPayments(){const el=document.querySelector('#payment-status');if(el)el.onchange=async e=>{state.paymentStatus=e.target.value;await loadPayments();render()};const methodsBox=document.querySelector('#checkout-methods-form');if(methodsBox){methodsBox.querySelectorAll('input[type=checkbox][name]').forEach(inp=>{inp.addEventListener('change',()=>{inp.closest('.pay-method')?.classList.toggle('is-on',inp.checked)})})}
document.querySelector('#save-checkout-methods')?.addEventListener('click',async()=>{const box=document.querySelector('#checkout-methods-form');if(!box)return;const checkoutMethods={};box.querySelectorAll('input[type=checkbox][name]').forEach(inp=>{checkoutMethods[inp.name]=inp.checked});try{state.paymentSettings=await api(root()+'/payments/settings',{method:'PUT',body:{checkoutMethods}});alert('Способы оплаты на витрине сохранены');render()}catch(err){alert(err.message)}});document.querySelectorAll('[data-check-payment]').forEach(b=>b.onclick=async()=>{try{await api(root()+`/payments/${b.dataset.checkPayment}/check`,{method:'POST'});await loadPayments();render()}catch(err){alert(err.message)}});document.querySelectorAll('[data-refund-payment]').forEach(b=>b.onclick=async()=>{if(!confirm('Оформить полный возврат?'))return;try{await api(root()+`/payments/${b.dataset.refundPayment}/refund`,{method:'POST',body:{}});await loadPayments();render()}catch(err){alert(err.message)}});document.querySelector('#payment-providers')?.addEventListener('click',()=>modal('Платёжные провайдеры',['yookassa','tbank','tochka','yapay','split'].map(code=>{const c=state.paymentSettings?.[code]||{};const labels={yookassa:'ЮKassa',tbank:'Т‑Банк',tochka:'Точка',yapay:'Я.Пэй',split:'Сплит'};return`<fieldset class="full"><legend>${labels[code]}</legend><label>Магазин / терминал<input name="${code}_shopId" value="${esc(c.shopId||c.terminalKey||'')}"></label><label>Секрет / токен<input name="${code}_secret" type="password" placeholder="${c.secretKeySet?'сохранён':''}"></label></fieldset>`}).join(''),async form=>{const fd=Object.fromEntries(new FormData(form));const body={};for(const code of ['yookassa','tbank','tochka','yapay','split']){body[code]={shopId:fd[`${code}_shopId`]||'',terminalKey:fd[`${code}_shopId`]||''};if(fd[`${code}_secret`]){body[code].secretKey=fd[`${code}_secret`];body[code].token=fd[`${code}_secret`]}}state.paymentSettings=await api(root()+'/payments/settings',{method:'PUT',body});render()},'wide'));document.querySelector('#payment-legal')?.addEventListener('click',()=>{const l=state.paymentSettings?.legal||{};const f=state.paymentSettings?.fiscal||{};modal('Юр.данные и чеки',`<label>Компания<input name="companyName" value="${esc(l.companyName||'')}"></label><label>ИНН<input name="inn" value="${esc(l.inn||'')}"></label><label>КПП<input name="kpp" value="${esc(l.kpp||'')}"></label><label>ОГРН<input name="ogrn" value="${esc(l.ogrn||'')}"></label><label class="full">Юр. адрес<input name="legalAddress" value="${esc(l.legalAddress||'')}"></label><label>НДС %<input name="vatRate" type="number" value="${l.vatRate??20}"></label><label>СНО<select name="taxSystem"><option value="osn" ${(l.taxSystem||'osn')==='osn'?'selected':''}>ОСН</option><option value="usn_income" ${l.taxSystem==='usn_income'?'selected':''}>УСН доходы</option><option value="usn_income_outcome" ${l.taxSystem==='usn_income_outcome'?'selected':''}>УСН доход-расход</option></select></label><label class="check full"><input name="receiptEnabled" type="checkbox" ${f.enabled!==false?'checked':''}> Фискальные чеки</label>`,async form=>{const fd=Object.fromEntries(new FormData(form));state.paymentSettings=await api(root()+'/payments/settings',{method:'PUT',body:{legal:{companyName:fd.companyName,inn:fd.inn,kpp:fd.kpp,ogrn:fd.ogrn,legalAddress:fd.legalAddress,vatRate:Number(fd.vatRate||20),taxSystem:fd.taxSystem,receiptEnabled:form.receiptEnabled.checked},fiscal:{enabled:form.receiptEnabled.checked,vatRate:Number(fd.vatRate||20),sno:fd.taxSystem}}});render()})})}
async function loadWarehouse(){if(!state.shop)return;[state.inventory,state.warehouseMetrics,state.warehouseMovements,state.stocktakes,state.reservations]=await Promise.all([api(root()+'/warehouse/inventory'),api(root()+'/warehouse/metrics'),api(root()+'/warehouse/movements?type='+state.warehouseType),api(root()+'/warehouse/stocktakes'),api(root()+'/warehouse/reservations')])}
function warehousePage(){const m=state.warehouseMetrics||{skuCount:0,totalStock:0,available:0,lowStock:0,outOfStock:0};return `<div class="toolbar"><div><h2>Склад</h2></div><button class="ghost" id="warehouse-stocktake">Инвентаризация</button><button class="primary" id="warehouse-adjust">Корректировка</button></div><div class="metrics">${[['SKU',m.skuCount,'Учётных позиций'],['Всего',m.totalStock,'Физический остаток'],['Доступно',m.available,'Можно продать'],['Низкий остаток',m.lowStock,'Не более 3 единиц']].map(([a,b,c])=>`<article><small>${a}</small><strong>${b}</strong><span>${c}</span></article>`).join('')}</div><div class="panel table"><div class="row head"><span>Товар</span><span>Артикул</span><span>Остаток</span><span>Резерв</span><span>Доступно</span></div>${state.inventory.map(x=>`<div class="row"><span><b>${esc(x.name)}</b><small>${esc(x.variantName||'Основной')}</small></span><span class="mono">${esc(x.sku)}</span><span>${x.stock}</span><span>${x.reserved||0}</span><span><i class="status">${x.available}</i></span></div>`).join('')||`<div class="empty">${emptyIcon('warehouse')}<h3>Складских позиций пока нет</h3><p>Позиции появятся после создания товаров.</p></div>`}</div><div class="toolbar"><h3>Резервы</h3></div><div class="panel table"><div class="row head"><span>Товар</span><span>Артикул</span><span>Кол-во</span><span>Статус</span><span></span></div>${(state.reservations||[]).map(r=>`<div class="row"><span><b>${esc(r.name||r.productId)}</b><small>${esc(r.orderId||'')}</small></span><span class="mono">${esc(r.sku||'')}</span><span>${r.quantity}</span><span><i class="status">${esc(r.status)}</i></span><span>${r.status==='active'?`<button class="ghost" data-release-res="${r.id}">Снять</button>`:''}</span></div>`).join('')||`<div class="empty">${emptyIcon('warehouse')}<h3>Резервов нет</h3><p>Резервы создаются при оформлении заказов.</p></div>`}</div><div class="toolbar"><h3>Последние движения</h3><select id="warehouse-type"><option value="all">Все типы</option>${ruOptions('moveType',['receipt','writeoff','transfer','stocktake','sale','return'],state.warehouseType)}</select></div><div class="panel table"><div class="row head"><span>Дата</span><span>Артикул</span><span>Тип</span><span>Изменение</span></div>${state.warehouseMovements.slice(0,50).map(x=>`<div class="row"><span>${new Date(x.createdAt).toLocaleString('ru-RU')}</span><span class="mono">${esc(x.sku)}</span><span>${esc(ru('moveType',x.type))}</span><span>${x.delta>0?'+':''}${x.delta}</span></div>`).join('')||`<div class="empty">${emptyIcon('warehouse')}<h3>Движений пока нет</h3><p>История остатков появится после операций.</p></div>`}</div>`}
function bindWarehouse(){const type=document.querySelector('#warehouse-type');if(type)type.onchange=async e=>{state.warehouseType=e.target.value;await loadWarehouse();render()};const button=document.querySelector('#warehouse-adjust');if(button)button.onclick=()=>modal('Корректировка остатка',`<label>Позиция<select name="key">${state.inventory.map(x=>`<option value="${x.productId}|${x.variantId||''}">${esc(x.name)} — ${esc(x.sku)}</option>`).join('')}</select></label><label>Изменение<input name="delta" type="number" required placeholder="10 или -3"></label><label class="full">Причина<input name="reason" required value="Ручная корректировка"></label>`,async form=>{const data=Object.fromEntries(new FormData(form));const [productId,variantId]=String(data.key).split('|');await api(root()+'/warehouse/adjust',{method:'POST',body:{productId,variantId:variantId||null,delta:Number(data.delta),reason:data.reason}});await Promise.all([loadWarehouse(),loadCatalog()]);render()});const stocktake=document.querySelector('#warehouse-stocktake');if(stocktake)stocktake.onclick=()=>modal('Инвентаризация',`${state.inventory.map((x,i)=>`<label class="full">${esc(x.name)} · ${esc(x.sku)}<input name="actual_${i}" type="number" min="0" value="${x.stock}"></label>`).join('')||'<p class="muted">Нет позиций</p>'}<label class="full">Заметка<input name="note" value=""></label>`,async form=>{const items=state.inventory.map((x,i)=>({productId:x.productId,variantId:x.variantId||null,actual:Number(form.querySelector(`[name="actual_${i}"]`).value)}));await api(root()+'/warehouse/stocktakes',{method:'POST',body:{note:new FormData(form).get('note')||'',items}});await Promise.all([loadWarehouse(),loadCatalog()]);render()},'wide');document.querySelectorAll('[data-release-res]').forEach(b=>b.onclick=async()=>{try{await api(root()+`/warehouse/reservations/${b.dataset.releaseRes}/release`,{method:'POST'});await loadWarehouse();render()}catch(err){alert(err.message)}})}

async function loadTeam(){state.team=await api(`/workspaces/${state.workspace.id}/team`)}
function teamPage(){const t=state.team||{members:[],invites:[],permissions:{}};const roles=t.permissions?.roles||{};return `<div class="toolbar"><div><h2>Команда</h2></div><button class="primary" id="invite-member">+ Пригласить</button></div><div class="panel table"><div class="row head"><span>Сотрудник</span><span>Роль</span><span>Права</span><span>Магазины</span><span></span></div>${t.members.map(m=>`<div class="row"><span><b>${esc(m.user?.name||'')}</b><small>${esc(m.user?.email||'')}</small></span><span><i class="status">${esc(ru('role',m.role))}</i></span><span><small>${esc((m.permissions||[]).slice(0,4).join(', '))}${(m.permissions||[]).length>4?'…':''}</small></span><span>${m.role==='owner'||m.role==='admin'?'Все магазины':(m.shops||[]).map(s=>esc(s.name)).join(', ')||'Нет доступа'}</span><span>${m.role==='owner'?'':`<button class="icon-btn danger" data-remove-member="${m.id}">×</button>`}</span></div>`).join('')}</div><div class="panel"><div class="panel-head"><h3>Матрица прав</h3></div>${Object.entries(roles).map(([role,perms])=>`<p><b>${esc(role)}</b>: <small>${esc(perms.join(', '))}</small></p>`).join('')||'<p class="muted">Права загрузятся с командой.</p>'}</div><div class="panel"><div class="panel-head"><h3>Ожидают принятия</h3></div>${t.invites.filter(i=>i.status==='pending').map(i=>`<p><b>${esc(i.email)}</b> · ${esc(i.role)} · до ${new Date(i.expiresAt).toLocaleDateString('ru-RU')}</p>`).join('')||'<p class="muted">Активных приглашений нет.</p>'}</div>`}
function bindTeam(){document.querySelector('#invite-member').onclick=()=>modal('Пригласить сотрудника',`<label>Email<input name="email" type="email" required></label><label>Роль<select name="role"><option value="viewer">Наблюдатель</option><option value="manager">Менеджер</option><option value="admin">Администратор</option></select></label><label class="full">Магазины<select name="shopIds" multiple>${state.shops.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label>`,async form=>{const fd=new FormData(form);const invite=await api(`/workspaces/${state.workspace.id}/team/invites`,{method:'POST',body:{email:fd.get('email'),role:fd.get('role'),shopIds:fd.getAll('shopIds')}});alert(`Приглашение создано.\nСсылка: ${invite.acceptUrl}\nСтатус почты: ${invite.mailStatus}`);await loadTeam();render()});document.querySelectorAll('[data-remove-member]').forEach(b=>b.onclick=async()=>{if(confirm('Удалить сотрудника?')){await api(`/workspaces/${state.workspace.id}/team/${b.dataset.removeMember}`,{method:'DELETE'});await loadTeam();render()}});const sw=document.querySelector('#shop-switcher');if(sw)sw.onchange=async e=>{state.shop=state.shops.find(s=>s.id===e.target.value);await Promise.all([loadCatalog(),loadOrders(),loadCustomers(),loadCampaigns()]);render()}}

async function loadStorefront(){
  [state.storefront,state.versions,state.themePresets]=await Promise.all([
    api(root()+'/storefront'),
    api(root()+'/storefront/versions'),
    api('/storefront/theme-presets'),
  ]);
  state.storefront.vitrina=Array.isArray(state.storefront.vitrina)?state.storefront.vitrina:[];
  if(state.vitrinaSlide==null)state.vitrinaSlide=0;
  if(!state.vitrinaPreviewKey)state.vitrinaPreviewKey=Date.now();
  try{state.telegram=await api(root()+'/telegram')}catch{}
}
const placementLabel=p=>p==='tiles'?'Плитки разделов':'Карусель баннеров';
function vitrinaItems(){return (state.storefront?.vitrina||[]).filter(x=>x&&x.imageUrl&&(x.placement==='carousel'||x.placement==='tiles')).slice().sort((a,b)=>Number(b.priority)-Number(a.priority)||String(a.name||'').localeCompare(String(b.name||''),'ru'))}
function storefrontPreviewUrl(){
  const slug=state.shop?.slug||'';
  let origin=location.origin;
  for(const raw of [state.telegram?.miniAppUrl,state.telegram?.storefrontUrl,state.telegram?.publicBaseUrl]){
    if(!raw) continue;
    try{origin=new URL(raw).origin;break}catch{}
  }
  const u=new URL('/',origin);
  u.searchParams.set('shop',slug);
  u.searchParams.set('preview','tg');
  u.searchParams.set('_',String(state.vitrinaPreviewKey||Date.now()));
  return u.toString();
}
function vitrinaPhonePreview(){
  const url=storefrontPreviewUrl();
  return `<div class="iphone-shell"><div class="iphone-bezel"><div class="iphone-dynamic-island" aria-hidden="true"></div><div class="iphone-screen tg-miniapp-preview"><iframe class="tg-prev-iframe" src="${esc(url)}" loading="eager" referrerpolicy="no-referrer-when-downgrade"></iframe></div></div></div><div class="tg-prev-actions"><button type="button" class="ghost" data-vitrina-preview-add="carousel">+ Баннер</button><button type="button" class="ghost" data-vitrina-preview-add="tiles">+ Плитка</button><a class="ghost" href="${esc(url)}" target="_blank" rel="noopener">Открыть</a></div>`;
}
function storefrontBuilder(){const d=state.storefront;if(!d)return `<div class="panel empty"><h3>Загрузка…</h3></div>`;const items=vitrinaItems();return `<div class="vitrina-page"><div class="vitrina-layout"><section class="vitrina-main"><div class="toolbar"><div><h2>Витрина</h2><small>Загрузите картинку — баннер или плитку. Без названий и ссылок.</small></div><div class="builder-actions"><button class="ghost" id="publish-storefront">Опубликовать</button><button class="ghost" id="new-vitrina-tile" type="button">+ Плитка</button><button class="primary" id="new-vitrina" type="button">+ Баннер</button><input id="vitrina-quick-file" type="file" accept="image/*" hidden></div></div><div class="panel table vitrina-table"><div class="row head"><span></span><span>Тип</span><span>Приоритет</span><span>Отображение</span><span></span></div>${items.length?items.map(item=>`<div class="row"><span class="vitrina-thumb">${item.imageUrl?`<img src="${esc(mediaUrl(item.imageUrl))}" alt="">`:'<i></i>'}</span><span class="vitrina-type"><b>${placementLabel(item.placement)}</b><small>${esc(item.name||'Изображение')}</small></span><span class="vitrina-priority num">${Number(item.priority||0)}</span><span class="vitrina-vis"><button type="button" class="icon-btn vitrina-eye ${item.visible===false?'off':''}" data-vitrina-toggle="${esc(item.id)}" title="${item.visible===false?'Скрыт':'Показан'}" aria-label="Видимость">${item.visible===false?'⊘':'👁'}</button></span><span class="actions"><button type="button" class="icon-btn" data-vitrina-edit="${esc(item.id)}" aria-label="Заменить">✎</button><button type="button" class="icon-btn" data-vitrina-menu="${esc(item.id)}" aria-label="Меню">⋮</button></span></div>`).join(''):`<div class="empty"><h3>Пока пусто</h3><p>Нажмите «+ Баннер» или «+ Плитка» и выберите изображение.</p></div>`}</div></section><aside class="vitrina-preview-pane"><div class="vitrina-preview-head"><b>iPhone · Mini App</b><small>Как в Telegram · сохранение сразу публикует</small></div>${vitrinaPhonePreview()}</aside></div></div>`}
async function persistVitrina(andPublish=true){
  const d=state.storefront;
  d.vitrina=vitrinaItems();
  state.storefront=await api(root()+'/storefront',{method:'PATCH',body:d});
  // Auto-publish so phone preview + Telegram Mini App stay in sync with admin edits.
  const shouldPublish=andPublish!==false;
  let result=state.storefront;
  if(shouldPublish){
    result=await api(root()+'/storefront/publish',{method:'POST'});
    state.versions=await api(root()+'/storefront/versions');
  }
  state.vitrinaPreviewKey=Date.now();
  return result;
}
function vitrinaFormFields(item={}){return `<div class="form-grid"><label class="full">Картинка<input name="imageUrl" id="vitrina-image-url" value="${esc(item.imageUrl||'')}" placeholder="Загрузите файл ниже"></label><label class="full ghost upload-button">Загрузить изображение<input id="vitrina-image-file" type="file" accept="image/*" hidden></label><label class="check full"><input name="visible" type="checkbox" ${item.visible!==false?'checked':''}> Показывать в магазине</label><input type="hidden" name="placement" value="${item.placement==='tiles'?'tiles':'carousel'}"><input type="hidden" name="priority" value="${Number(item.priority??1)}"></div>`}
async function addVitrinaFromFile(file, placement='carousel'){
  if(!file)return;
  const uploaded=await api(root()+'/media',{method:'POST',body:{dataUrl:await fileToDataUrl(file),originalName:file.name}});
  const label=placement==='tiles'?'Плитка':'Баннер';
  const next={
    id:crypto.randomUUID(),
    name:label,
    placement:placement==='tiles'?'tiles':'carousel',
    title:'',
    subtitle:'',
    linkUrl:'',
    imageUrl:uploaded.url,
    priority:Math.max(1,...vitrinaItems().map(x=>Number(x.priority||0)),0)+1,
    visible:true,
  };
  state.storefront.vitrina=[...vitrinaItems(),next];
  await persistVitrina(true);
  render();
}
function pickVitrinaImage(placement='carousel'){
  const input=document.querySelector('#vitrina-quick-file');
  if(!input){
    const temp=document.createElement('input');
    temp.type='file';temp.accept='image/*';
    temp.onchange=async()=>{try{await addVitrinaFromFile(temp.files?.[0],placement)}catch(err){alert(err.message)}};
    temp.click();
    return;
  }
  input.value='';
  input.onchange=async()=>{
    try{await addVitrinaFromFile(input.files?.[0],placement)}
    catch(err){alert(err.message)}
  };
  input.click();
}
function openVitrinaEditor(item=null,defaults={}){
  if(!item){
    pickVitrinaImage(defaults.placement==='tiles'?'tiles':'carousel');
    return;
  }
  const seed={...item};
  const wrap=modal('Заменить изображение',vitrinaFormFields(seed),async form=>{
    const fd=Object.fromEntries(new FormData(form));
    if(!fd.imageUrl)throw new Error('Загрузите изображение');
    const next={
      id:item.id,
      name:item.name|| (item.placement==='tiles'?'Плитка':'Баннер'),
      placement:item.placement==='tiles'?'tiles':'carousel',
      title:'',
      subtitle:'',
      linkUrl:'',
      imageUrl:fd.imageUrl||'',
      priority:Number(item.priority||0),
      visible:form.visible.checked,
    };
    const list=vitrinaItems().filter(x=>x.id!==next.id);
    list.push(next);
    state.storefront.vitrina=list;
    await persistVitrina(true);
    render();
  },'large');
  const file=wrap.querySelector('#vitrina-image-file');
  const urlInput=wrap.querySelector('#vitrina-image-url');
  if(file)file.onchange=async()=>{
    const f=file.files?.[0];if(!f)return;
    try{
      const uploaded=await api(root()+'/media',{method:'POST',body:{dataUrl:await fileToDataUrl(f),originalName:f.name}});
      urlInput.value=uploaded.url;
    }catch(err){alert(err.message)}
  };
}
function bindVitrinaPreview(){
  document.querySelectorAll('[data-vitrina-preview-add]').forEach(btn=>btn.onclick=e=>{
    e.stopPropagation();
    pickVitrinaImage(btn.dataset.vitrinaPreviewAdd==='tiles'?'tiles':'carousel');
  });
}
function bindStorefront(){
  const d=state.storefront;
  if(!d)return;
  if(bindStorefront._carousel){clearInterval(bindStorefront._carousel);bindStorefront._carousel=null}
  document.querySelector('#new-vitrina')?.addEventListener('click',()=>pickVitrinaImage('carousel'));
  document.querySelector('#new-vitrina-tile')?.addEventListener('click',()=>pickVitrinaImage('tiles'));
  document.querySelector('#publish-storefront')?.addEventListener('click',async()=>{
    try{
      const result=await persistVitrina(true);
      alert(`Витрина опубликована · v${result.version}`);
      render();
    }catch(err){alert(err.message)}
  });
  document.querySelectorAll('[data-vitrina-edit]').forEach(btn=>btn.onclick=()=>{
    const item=vitrinaItems().find(x=>x.id===btn.dataset.vitrinaEdit);
    if(item)openVitrinaEditor(item);
  });
  document.querySelectorAll('[data-vitrina-toggle]').forEach(btn=>btn.onclick=async()=>{
    const item=vitrinaItems().find(x=>x.id===btn.dataset.vitrinaToggle);
    if(!item)return;
    item.visible=item.visible===false;
    try{await persistVitrina(true);render()}catch(err){alert(err.message)}
  });
  document.querySelectorAll('[data-vitrina-menu]').forEach(btn=>btn.onclick=async()=>{
    const item=vitrinaItems().find(x=>x.id===btn.dataset.vitrinaMenu);
    if(!item)return;
    const action=prompt('Введите: replace / hide / delete','replace');
    if(!action)return;
    if(action==='replace'||action==='edit')return openVitrinaEditor(item);
    if(action==='hide'||action==='show'){
      item.visible=action==='show';
      await persistVitrina(true);
      return render();
    }
    if(action==='delete'&&confirm('Удалить изображение?')){
      state.storefront.vitrina=vitrinaItems().filter(x=>x.id!==item.id);
      await persistVitrina(true);
      render();
    }
  });
  bindVitrinaPreview();
}

