async function loadDelivery(){if(!state.shop)return;[state.deliveryMethods,state.shipments,state.courierZones,state.apiship]=await Promise.all([api(root()+'/delivery/methods'),api(root()+'/delivery/shipments'),api(root()+'/delivery/zones'),api(root()+'/delivery/apiship')])}
