function helpPage(){const msgs=state.supportThread?.messages||[];const art=state.helpArticle;return `<div class="help-layout"><aside class="panel help-kb"><div class="panel-head"><div><h2>База знаний</h2><small>Подсказки по платформе</small></div></div><div class="help-filters"><div class="search help-search"><span class="search-ico" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="6.5"/><path d="m16.2 16.2 4.3 4.3"/></svg></span><input id="help-search" value="${esc(state.helpQuery)}" placeholder="Поиск: оплата, ApiShip, Telegram…"></div><select id="help-section"><option value="">Все разделы</option>${(state.helpSections||[]).map(s=>`<option value="${esc(s)}" ${state.helpSection===s?'selected':''}>${esc(s)}</option>`).join('')}</select></div><div class="help-list">${(state.helpArticles||[]).map(a=>`<button type="button" class="help-item ${art?.id===a.id?'active':''}" data-help-article="${a.id}"><small>${esc(a.section)}</small><b>${esc(a.title)}</b></button>`).join('')||'<p class="muted">Ничего не найдено.</p>'}</div></aside><section class="panel help-article">${art?`<div class="panel-head"><div><small>${esc(art.section)}</small><h2>${esc(art.title)}</h2></div></div><div class="help-body">${esc(art.content).replace(/\n/g,'<br>')}</div><div class="help-tags">${(art.tags||[]).map(t=>`<span class="pill">${esc(t)}</span>`).join('')}</div>`:`<div class="panel empty">${emptyIcon('help')}<h3>Выберите статью</h3><p>Или спросите в чате поддержки справа — бот подскажет материал из базы.</p></div>`}</section><aside class="panel help-chat"><div class="panel-head"><div><h2>Чат поддержки</h2><small>Платформа GStore</small></div><i class="status ${state.supportThread?.status==='open'?'paid':'cancelled'}">${esc(state.supportThread?.status||'new')}</i></div><div class="support-messages" id="support-messages">${msgs.map(m=>`<div class="support-msg ${m.role}"><b>${m.role==='user'?'Вы':'Поддержка'}</b><p>${esc(m.text).replace(/\n/g,'<br>')}</p>${m.articleId?`<button type="button" class="ghost" data-help-article="${esc(m.articleId)}">Открыть статью</button>`:''}<small>${m.createdAt&&m.id!=='welcome'?new Date(m.createdAt).toLocaleString('ru-RU'):''}</small></div>`).join('')}</div><form id="support-form" class="support-compose"><textarea name="text" rows="3" required placeholder="Напишите вопрос… Например: как подключить ЮKassa">${esc(state.supportDraft)}</textarea><div class="modal-actions"><button class="primary">Отправить</button></div></form><div class="toolbar"><h3>Тикеты</h3></div><div class="panel table compact">${(state.supportTickets||[]).slice(0,8).map(t=>`<div class="row"><span><b>#${t.number}</b> ${esc(t.subject)}</span><span><i class="status">${esc(t.status)}</i></span></div>`).join('')||'<p class="muted">Обращений пока нет.</p>'}</div></aside></div>`}
function bindHelp(){const search=document.querySelector('#help-search');if(search){search.oninput=e=>{clearTimeout(bindHelp.t);bindHelp.t=setTimeout(async()=>{state.helpQuery=e.target.value;await loadHelp();render()},220)};}const sec=document.querySelector('#help-section');if(sec)sec.onchange=async e=>{state.helpSection=e.target.value;await loadHelp();render()};document.querySelectorAll('[data-help-article]').forEach(b=>b.onclick=async()=>{const id=b.dataset.helpArticle;state.helpArticle=state.helpArticles.find(a=>a.id===id)||await api('/help/articles/'+id);render();document.querySelector('#support-messages')?.scrollTo?.(0,1e9)});const form=document.querySelector('#support-form');if(form)form.onsubmit=async e=>{e.preventDefault();const text=new FormData(form).get('text');state.supportDraft='';try{const res=await api(root()+'/support/messages',{method:'POST',body:{text}});state.supportThread=res.thread;if(res.suggestedArticle)state.helpArticle=res.suggestedArticle;await loadHelp();render();requestAnimationFrame(()=>document.querySelector('#support-messages')?.scrollTo?.(0,1e9))}catch(err){alert(err.message)}};requestAnimationFrame(()=>document.querySelector('#support-messages')?.scrollTo?.(0,1e9))}
function bindSupportFab(){if(document.querySelector('#support-fab'))return;if(!state.shop||!session.token)return;const fab=document.createElement('button');fab.id='support-fab';fab.type='button';fab.className='support-fab';fab.title='Чат поддержки';fab.textContent='?';fab.onclick=async()=>{state.route='help';await loadHelp();render()};document.body.append(fab)}

async function loadChats(){if(!state.shop)return;[state.chats,state.channelPosts]=await Promise.all([api(root()+'/chats'),api(root()+'/channel-posts')])}
function bindChats(){document.querySelectorAll('[data-chat-open]').forEach(b=>b.onclick=async()=>{const [channel,externalUserId]=b.dataset.chatOpen.split('|');const messages=await api(root()+`/chats/${channel}/${encodeURIComponent(externalUserId)}`);const nick=String((state.chats||[]).find(t=>t.channel===channel&&String(t.externalUserId)===String(externalUserId))?.username||'').replace(/^@/,'').trim();modal(nick?`Диалог @${nick}`:'Диалог',`<div class="full">${messages.map(m=>`<p><b>${esc(m.direction)}</b>: ${esc(m.text)}</p>`).join('')||'<p class="muted">Пусто</p>'}</div><label class="full">Ответ<textarea name="text" required></textarea>`,async form=>{const text=new FormData(form).get('text');await api(root()+'/chats/reply',{method:'POST',body:{channel,externalUserId,text}});await loadChats();render()},'wide')})}

async function loadIntegrationsHub(){if(!state.shop)return;[state.importJobs,state.erpConnections,state.integrationLogs,state.maxChannel,state.telegram]=await Promise.all([api(root()+'/import-jobs'),api(root()+'/erp'),api(root()+'/integration-logs'),api(root()+'/max'),api(root()+'/telegram')]);state.feeds=[]}
function integrationsHubPage(){const mx=state.maxChannel||{};return `<div class="settings-stack">${telegramPanelHtml()}<div class="panel"><div class="panel-head"><div><h2>MAX</h2><small>${mx.connected?('@'+esc(mx.botUsername)):'канал магазина'}${mx.connected?` · ${mx.mode==='live'?'боевой режим':'тест'}`:''}</small></div><i class="status ${mx.connected?'paid':'cancelled'}">${mx.connected?'Активен':'Выкл'}</i></div><form id="max-form" class="form-grid"><label class="full">Токен<input name="token" type="password" ${mx.connected?'':'required'}></label><label>ID канала<input name="channelId" value="${esc(mx.channelId||'')}"></label><label class="full">Адрес для уведомлений<input name="publicUrl" value="${esc(mx.publicUrl||'')}"></label><div class="full modal-actions"><button class="primary">${mx.connected?'Обновить':'Подключить'}</button>${mx.connected?'<button type="button" class="ghost danger" id="max-disconnect">Отключить</button>':''}</div></form></div><div class="panel"><div class="panel-head"><div><h2>Периодический импорт</h2></div><button class="primary" id="import-job-add">+ Задача</button></div>${(state.importJobs||[]).map(j=>`<p><b>${esc(j.url)}</b> · каждые ${j.intervalMinutes} мин · ${esc(j.lastStatus||'pending')} <button class="ghost" data-import-run="${j.id}">Запуск</button><button class="icon-btn danger" data-import-del="${j.id}">×</button></p>`).join('')||'<p class="muted">Задач импорта нет.</p>'}</div><div class="panel"><div class="panel-head"><div><h2>Учётные системы</h2></div><button class="primary" id="erp-add">+ Подключение</button></div>${(state.erpConnections||[]).map(c=>`<p><b>${esc(c.name||c.provider)}</b> · ${esc(c.status||'')} <button class="ghost" data-erp-test="${c.id}">Тест</button><button class="ghost" data-erp-sync="${c.id}">Синхронизация</button><button class="icon-btn danger" data-erp-del="${c.id}">×</button></p>`).join('')||'<p class="muted">МойСклад / 1С / YClients ещё не подключены.</p>'}</div><div class="panel"><div class="panel-head"><h3>Логи интеграций</h3></div><div class="panel table"><div class="row head"><span>Провайдер</span><span>Действие</span><span>Статус</span><span>Сообщение</span></div>${(state.integrationLogs||[]).slice(0,30).map(l=>`<div class="row"><span>${esc(l.provider)}</span><span>${esc(l.action)}</span><span>${esc(l.status)}</span><span>${esc(l.message||'')}</span></div>`).join('')||'<p class="muted">Логов пока нет.</p>'}</div></div></div>`}
function bindIntegrationsHub(){bindTelegramForm(async()=>{await loadIntegrationsHub();render()});const maxForm=document.querySelector('#max-form');if(maxForm)maxForm.onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(maxForm));state.maxChannel=await api(root()+'/max/connect',{method:'POST',body});render()};document.querySelector('#max-disconnect')?.addEventListener('click',async()=>{await api(root()+'/max',{method:'DELETE'});await loadIntegrationsHub();render()});document.querySelector('#import-job-add')?.addEventListener('click',()=>modal('Импорт по URL',`<label class="full">URL файла<input name="url" type="url" required placeholder="https://.../catalog.csv"></label><label>Интервал, мин<input name="intervalMinutes" type="number" value="60" min="15"></label><label>Тип<select name="type"><option value="csv">CSV</option></select></label>`,async form=>{const body=Object.fromEntries(new FormData(form));body.intervalMinutes=Number(body.intervalMinutes);await api(root()+'/import-jobs',{method:'POST',body});await loadIntegrationsHub();render()}));document.querySelectorAll('[data-import-run]').forEach(b=>b.onclick=async()=>{try{const r=await api(root()+`/import-jobs/${b.dataset.importRun}/run`,{method:'POST'});alert('Импорт: '+JSON.stringify(r));await loadIntegrationsHub();render()}catch(err){alert(err.message)}});document.querySelectorAll('[data-import-del]').forEach(b=>b.onclick=async()=>{await api(root()+`/import-jobs/${b.dataset.importDel}`,{method:'DELETE'});await loadIntegrationsHub();render()});document.querySelector('#erp-add')?.addEventListener('click',()=>modal('ERP подключение',`<label>Провайдер<select name="provider"><option value="moysklad">МойСклад</option><option value="one_c">1С</option><option value="yclients">YClients</option></select></label><label class="full">Токен<input name="token"></label><label>Логин<input name="login"></label><label>Пароль<input name="password" type="password"></label><label class="full">Базовый URL<input name="baseUrl" placeholder="https://"></label>`,async form=>{await api(root()+'/erp',{method:'POST',body:Object.fromEntries(new FormData(form))});await loadIntegrationsHub();render()}));document.querySelectorAll('[data-erp-test]').forEach(b=>b.onclick=async()=>{const r=await api(root()+`/erp/${b.dataset.erpTest}/test`,{method:'POST'});alert(r.ok?'OK: '+r.detail:'Fail: '+r.detail);await loadIntegrationsHub();render()});document.querySelectorAll('[data-erp-sync]').forEach(b=>b.onclick=async()=>{const r=await api(root()+`/erp/${b.dataset.erpSync}/sync`,{method:'POST',body:{direction:'pull'}});alert('Sync: '+JSON.stringify(r.stats));await loadIntegrationsHub();render()});document.querySelectorAll('[data-erp-del]').forEach(b=>b.onclick=async()=>{await api(root()+`/erp/${b.dataset.erpDel}`,{method:'DELETE'});await loadIntegrationsHub();render()})}
